                var hn=0;
                var ub=ui.selected.buttons;
                for(var i=0;i<ub.length;i++){
                    if(ss.contains(ub[i].link)) sn++;
                    else hn++;
                }
                return !(sn>=hs.length&&ss.contains(button.link)||hn>=ss.length&&hs.contains(button.link));
