            "yxsjn_longluo":{
                audio: "ext:华夏风云/audio/peiyin:2",
    yuyu: true,
    mark: false,
    _priority: Math.floor(Math.random() * 151) + 50,
    direct: true,
    forced: true,
    trigger: { player: "phaseDiscardBefore" },
    filter: function(event, player) {
        return player.countCards('h') > 0 && game.hasPlayer(target => target != player);
    },
    async content(event, trigger, player) {
        const result = await player.chooseCardTarget({
            prompt: '【笼络】请选择弃置的牌和承受伤害转移的英雄（数量需相等）',
            filterCard: true,
            position: 'h',
            selectCard: [1, Infinity],
            filterTarget: lib.filter.notMe,
            selectTarget: function() { return ui.selected.cards.length; },
            ai1: function(card) { return 7 - get.value(card); },
            ai2: function(target) {
                var player = get.player();
                if (target.isFriendsOf(player)) return 999; 
                return -999; 
            }
        }).forResult();

        if (!result.bool || !result.targets || result.targets.length === 0) return;

        player.logSkill('yxsjn_longluo');

        var cards = result.cards;
        var targets = result.targets;
        await player.discard(cards);

        // ★ 存储目标列表
        player.storage.bjbj_longluo_targets = targets;

        // ★ 挂载伤害转移监听器（全局）
        if (!player.hasSkill('yxsjn_longluo_global')) {
            player.addSkill('yxsjn_longluo_global');
        }

        // ★ 给每个目标挂上标记，并牵上连线
        for (var i = 0; i < targets.length; i++) {
            var target = targets[i];
            
            // ★ 新增：虚拟线（绿色线代表笼络/控制）
            player.line(target, 'green'); 
            
            target.addSkill('yxsjn_longluo_标记');
            target.update();
            
            // ★ 删掉了这里的 target.popup('笼络·转移', '#ff00ff');
            game.log(target, '受到【笼络】标记，本回合前受到的1点伤害将转移给', player);
        }

        // ★ 自动挂载清理器：在施法者回合结束时清理
        if (!player.hasSkill('yxsjn_longluo_clear')) {
            player.addSkill('yxsjn_longluo_clear');
        }
    }
},

// ★ 全局伤害转移监听器（宇文化及）
"yxsjn_longluo_global": {
    _priority: Math.floor(Math.random() * 151) + 50,
    trigger: { global: "damageBegin4" }, 
    forced: true,
    popup: false,
    filter: function(event, player) {
        if (!player.isAlive() || event.num <= 0) return false;
        var targets = player.storage.bjbj_longluo_targets || [];
        return targets.includes(event.player);
    },
    content: function() {
        var transfer = Math.min(1, trigger.num);
        trigger.num = Math.max(0, trigger.num - transfer);
        player.damage(transfer, 'nocard');
        game.log(trigger.player, '【笼络】标记生效中，将', transfer, '点伤害转移给', player);
    }
},


"yxsjn_longluo_clear": {
    _priority: Math.floor(Math.random() * 151) + 50,
    trigger: { player: "phaseBegin" }, // ★ 核心修改：这里改成 phaseBegin
    forced: true,
    popup: false,
    content: function() {
        var targets = player.storage.bjbj_longluo_targets || [];
        
        for (var p of game.players) {
            if (targets.includes(p)) {
                p.removeSkill('yxsjn_longluo_标记');
                p.update();
            }
        }
        
        if (player.hasSkill('yxsjn_longluo_global')) {
            player.removeSkill('yxsjn_longluo_global');
        }
        
        delete player.storage.bjbj_longluo_targets;
        player.removeSkill('yxsjn_longluo_clear');
        // ★ 顺便把日志里的“回合结束”改成“回合开始”
        game.log(player, '【笼络】标记已因新回合开始而正常解除，效果结束');
    }
},

