chuanqi_huying_block: {
	charlotte: true,
	mark: true,
	marktext: "禁",
	init: function (player, skill) {
		player.addSkillBlocker(skill);
	},
	onremove: function (player, skill) {
		player.removeSkillBlocker(skill);
		delete player.storage.chuanqi_huying_type;
	},
	skillBlocker: function (skill, player) {
		if (!lib.skill[skill]) return false;

		var type = player.storage.chuanqi_huying_type;
		if (!type) return false;

		var info = lib.skill[skill];

		if (type == "red") {
			// 红色：封印非锁定技（非 charlotte、非 forced 的主动技能）
			if (info.charlotte) return false;
			if (info.forced) return false;
			return true;
		}

		if (type == "black") {
			// 黑色：封印锁定技（forced 或 charlotte 的被动技能）
			return !!(info.forced || info.charlotte);
		}

		return false;
	},
	intro: {
		content: function (storage, player) {
			var type = player.storage.chuanqi_huying_type;
			if (type == "red") return "非锁定技已失效，直到施放者下个回合开始";
			if (type == "black") return "锁定技已失效，直到施放者下个回合开始";
			return "无效果";
		},
	},
},
			
