        if (event.cards && event.cards.length) eventCards.addArray(event.cards);
        if (event.card) {
          if (event.card.cards && event.card.cards.length) eventCards.addArray(event.card.cards);
          else if (event.card.cardid) eventCards.add(event.card);
        }

        return eventCards.some(c => list.includes(c.cardid));
