      if (get.type2(name) !== "trick" || name === "wuxie") return false;
      const usedBySkill = player.getStorage("yxs_siyi_used") || [];
      if (usedBySkill.includes(name)) return false;
      if (player.hasHistory("useCard", evt => evt.card?.name === name)) return false;
      return player.countCards("he") > 0;
