  yxs_jianji: {
    audio: "ext:华夏风云/audio/peiyin:2",
    trigger: { player: "phaseEnd" },
    filter(event, player) {
      return Boolean(ui.discardPile && ui.discardPile.childNodes.length > 0);
    },
    async cost(event, trigger, player) {
      event.result = await player
        .chooseBool(
          get.prompt("yxs_jianji"),
          "展示弃牌堆顶的牌并交给手牌最少的角色，直到点数之和达到13"
        )
        .set("ai", () => true)
        .forResult();
    },
    async content(event, trigger, player) {
      let sum = 0;
      while (sum < 13 && ui.discardPile.childNodes.length > 0) {
        // 取弃牌堆顶的一张牌
        const card = ui.discardPile.lastChild;
        if (!card) break;

        const num = get.number(card) || 0;
        sum += num;

        // 展示卡牌
        player.showCards(card, `${get.translation(player)}发动【兼济】（当前点数和：${sum}/13）`);

        // 获取手牌最少的存活角色
        const minCount = Math.min(...game.filterPlayer().map(p => p.countCards("h")));
        const targets = game.filterPlayer(p => p.countCards("h") === minCount);

        if (targets.length === 1) {
          await targets[0].gain(card, "gain2");
        } else if (targets.length > 1) {
          // 若有多名手牌最少角色，由白居易选择交给谁
          const result = await player
            .chooseTarget(
              `请选择一名手牌最少（${minCount}张）的角色获得此牌：`,
              (c, p, target) => targets.includes(target),
              true
            )
            .set("ai", target => get.attitude(player, target))
            .forResult();

          if (result.bool && result.targets.length) {
            await result.targets[0].gain(card, "gain2");
          } else {
            await targets[0].gain(card, "gain2");
          }
        }
        await game.delayx();
      }
    },
    ai: {
      expose: 0.2,
    },
  },

