  yxs_liuzhe: {
    audio: "ext:华夏风云/audio/peiyin:2",
    trigger: {
      target: "useCardToTargeted",
      player: "phaseZhunbeiBegin", // 下个回合开始前清空印记
    },
    filter(event, player) {
      // 回合开始时触发清理
      if (event.name === "phaseZhunbei") {
        return player.countMark("yxs_liuzhe") > 0;
      }
      // 成为目标时触发
      if (!event.player || event.player === player) return false;
      const card = event.card;
      const isSha = card.name === "sha";
      const isSingleTrick = get.type2(card) === "trick" && event.targets && event.targets.length === 1;
      if (!isSha && !isSingleTrick) return false;

      // 判定来源体力或手牌数是否大于自己
      const source = event.player;
      return source.hp > player.hp || source.countCards("h") > player.countCards("h");
    },
    forced: true,
    async content(event, trigger, player) {
      if (trigger.name === "phaseZhunbei") {
        player.removeMark("yxs_liuzhe", player.countMark("yxs_liuzhe"));
      } else {
        player.addMark("yxs_liuzhe", 1);
      }
    },
    // 距离修正：其他角色计算与你的距离增加
    mod: {
      globalTo(from, to, current) {
        if (to.countMark("yxs_liuzhe") > 0 && from !== to) {
          return current + to.countMark("yxs_liuzhe");
        }
      },
    },
    intro: {
      content: "其他角色与你计算距离+#",
    },
  },

  yxs_laotao: {
    audio: "ext:华夏风云/audio/peiyin:2",
    init(player) {
      player.storage.yxs_laotao_dist = {};
      for (const other of game.filterPlayer(p => p !== player)) {
        player.storage.yxs_laotao_dist[other.playerid] = get.distance(other, player);
      }
    },
    trigger: {
      global: [
        "equipAfter",
        "loseAfter",
        "dieAfter",
        "phaseZhunbeiBegin",
        "phaseJieshuEnd",
        "addMarkAfter",
        "removeMarkAfter",
      ],
    },
    filter(event, player) {
      if (!player.isIn()) return false;
      if (!player.storage.yxs_laotao_dist) player.storage.yxs_laotao_dist = {};

      let changed = false;
      for (const other of game.filterPlayer(p => p !== player)) {
        const currentDist = get.distance(other, player);
        const prevDist = player.storage.yxs_laotao_dist[other.playerid];
        if (prevDist !== undefined && prevDist !== currentDist) {
          changed = true;
          break;
        }
      }
      return changed;
    },
    forced: true,
    async content(event, trigger, player) {
      // 重新记录当前全场对苏轼的距离
      for (const other of game.filterPlayer(p => p !== player)) {
        player.storage.yxs_laotao_dist[other.playerid] = get.distance(other, player);
      }
      await player.draw(1);
    },
  },
           
