                        "GXS_zhuolve": {
                            audio: "ext:华夏风云/audio/peiyin:2",
                            enable: 'phaseUse',
                            usable: 1,
                            delay: false,
                            filter(event, player) {
                                if (player.countCards('h', {
                                        color: 'black'
                                    }) == 0 && player.isHealthy()) return false;
                                return player.countCards('h') > 0;
                            },
                            content() {
                                'step 0'
                                player.showHandcards();
                                game.delay(0.5);
                                'step 1'
                                var list = [];
                                if (player.countCards('h', {
                                        color: 'red'
                                    }) && player.isDamaged()) list.push('红色')
                                if (player.countCards('h', {
                                        color: 'black'
                                    })) list.push('黑色')
                                if (list.length) {
                                    player.chooseControl(list).set('ai', function() {
                                        var player = _status.event.player;
                                        if (player.countCards('h', {
                                                color: 'red'
                                            }) == 1 && player.isDamaged() && list.includes('红色')) return '红色';
                                        if (player.countCards('h', {
                                                color: 'black'
                                            }) == 1 && list.includes('黑色')) return '黑色';
                                        return list.randomGet();
                                    });
                                }
                                'step 2'
                                if (result.control) {
                                    event.control = result.control;
                                    var cards;
                                    if (event.control == '红色') {
                                        cards = player.getCards('h', {
                                            color: 'red'
                                        });
                                        player.discard(cards);
                                        player.recover();
                                        event.finish();
                                    } else {
                                        cards = player.getCards('h', {
                                            color: 'black'
                                        });
                                        player.discard(cards);
                                        player.chooseUseTarget({
                                            name: 'nanman',
                                            isCard: true
                                        }, true);
                                        event.finish();
                                    }
                                }
                            },
                            contentAfter() {
                                var list = game.filterPlayer(function(current) {
                                    return current.hp > player.hp;
                                }).sortBySeat();

                                if (list.length) {
                                    if (player.getStat().skill.GXS_zhuolve > 0) player.getStat().skill.GXS_zhuolve--;
                                    event.finish();
                                }
                            },


                            ai: {
                                order(item, player) {
                                    if (player.countCards('h', {
                                            color: 'red'
                                        }) == 1) return 10;
                                    if (player.countCards('h', {
                                            color: 'black'
                                        }) == 1) return 10;
                                    return 1;
                                },
                                result: {
                                    player(player, target) {
                                        var eff = 0;
                                        if (player.countCards('h', {
                                                color: 'black'
                                            }) == 1) {
                                            for (var i = 0; i < game.players.length; i++) {
                                                if (game.players[i] == player || get.distance(game.players[i], player) > 1) continue;
                                                var nh = game.players[i].countCards('h');
                                                eff += (get.attitude(game.players[i], player) > 0 ? -1 : 1) * (3 - nh);
                                                if (get.mode() == 'identity') {
                                                    if (game.players[i].isZhu && game.players[i].hp <= 1 && nh <= 2 && get.attitude(player, game.players[i]) > 0) eff -= 100;
                                                }
                                            }
                                        }
                                        if (player.countCards('h', {
                                                color: 'red'
                                            }) == 1 && player.isDamaged()) eff += 10
                                        return eff;
                                    },
                                }
                            }
                        },
                        
