         "GXS_guyong": {
	audio: "ext:华夏风云/audio/peiyin:2",
	enable: ["chooseToUse", "chooseToRespond"],
	filter(event, player) {
		if (event.GXS_guyong_failed) return false;
		var used = player.getStorage("GXS_guyong_used") || [];
		var can_sha = !used.includes('sha') && event.filterCard({ name: "sha", isCard: true }, player, event);
		var can_shan = !used.includes('shan') && event.filterCard({ name: "shan", isCard: true }, player, event);
		if (!can_sha && !can_shan) return false;
		
		var max_hand = Math.max(...game.players.map(p => p.countCards('h')));
		if (max_hand <= 0) return false;
		return game.hasPlayer(p => p.countCards('h') === max_hand && p.countCards("he") > 0);
	},
	chooseButton: {
		dialog(event, player) {
			var used = player.getStorage("GXS_guyong_used") || [];
			var list = [];
			if (!used.includes('sha') && event.filterCard({ name: "sha", isCard: true }, player, event)) {
				list.push(["基本", "", "sha"]);
			}
			if (!used.includes('shan') && event.filterCard({ name: "shan", isCard: true }, player, event)) {
				list.push(["基本", "", "shan"]);
			}
			return ui.create.dialog("孤勇", [list, "vcard"]);
		},
		filter(button, player) {
			return get.event().getParent().filterCard({ name: button.link[2], nature: button.link[3], isCard: true }, player, _status.event.getParent());
		},
		check(button) {
			if (get.event().getParent().type != "phase") {
				return 1;
			}
			return get.event().player.getUseValue({ name: button.link[2], nature: button.link[3], isCard: true });
		},
		backup(links, player) {
			return {
				viewAs: {
					name: links[0][2],
					nature: links[0][3],
					isCard: true,
				},
				filterCard: () => false,
				selectCard: -1,
				log: false,
				async precontent(event, trigger, player) {
					let stop = false;
					var max_hand = Math.max(...game.players.map(p => p.countCards('h')));
					var candidates = game.filterPlayer(p => p.countCards('h') === max_hand);
					
					const result = await player
						.chooseTarget("请选择一名手牌数最多（" + max_hand + "张）的角色", "弃置其一张牌，若此牌为基本牌，则视为你使用/打出之", (card, player, target) => {
							return candidates.includes(target) && target.countCards('he') > 0;
						})
						.set("ai", target => 1 - get.sgn(get.attitude(get.player(), target)))
						.forResult();
					if (result?.bool) {
						const target = result.targets[0];
						player.logSkill("GXS_guyong", target);
						const result2 = await player
							.discardPlayerCard(target, "he", true)
							.set("prompt2", "若弃置的牌为基本牌，则视为你使用/打出之")
							.set("ai", button => {
								var card = button.link;
								if (card.isKnownBy(get.event().player) && get.type(card) === 'basic') {
									return 114514;
								}
								return 1 + Math.random();
							})
							.forResult();
						if (result2?.bool) {
							const card = result2.cards[0];
							
							var used = player.getStorage("GXS_guyong_used") || [];
							used.push(event.result.card.name);
							player.setStorage("GXS_guyong_used", used);
							
							if (get.type(card, target) === 'basic') {
								player.popup("洗具");
								stop = true;
							} else {
								player.popup("杯具");
							}
						}
					}
					if (!stop) {
						const evt = event.getParent();
						evt.set("GXS_guyong_failed", true);
						evt.goto(0);
						delete evt.openskilldialog;
						return;
					}
				},
			};
		},
		prompt(links, player) {
			const nature = get.translation(links[0][3]) || "";
			const name = "【" + get.translation(links[0][2]) + "】";
			return "选择一名其他角色视为对其使用" + nature + name;
		},
	},
	ai: {
		order: 10,
		respondSha: true,
		respondShan: true,
		skillTagFilter(player, tag) {
			const name = tag == "respondSha" ? "sha" : "shan";
			return lib.skill.GXS_guyong.hiddenCard(player, name);
		},
		result: {
			player(player) {
				if (_status.event.dying && get.attitude(player, _status.event.dying) <= 0) {
					return 0;
				}
				var max_hand = Math.max(...game.players.map(p => p.countCards('h')));
				if (max_hand <= 0) return 0;
				return game.hasPlayer(target => {
					if (get.attitude(player, target) > 0) {
						return false;
					}
					return target.countCards('h') === max_hand && target.countCards("he") > 0;
				})
					? 1
					: 0;
			},
		},
	},
	hiddenCard(player, name) {
		if (!lib.inpile.includes(name) || !["sha", "shan"].includes(name) || player.isTempBanned("GXS_guyong")) {
			return false;
		}
		var used = player.getStorage("GXS_guyong_used") || [];
		if (used.includes(name)) return false;
		
		var max_hand = Math.max(...game.players.map(p => p.countCards('h')));
		if (max_hand <= 0) return false;
		return game.hasPlayer(target => {
			return target.countCards('h') === max_hand && target.countCards("he") > 0;
		});
	},
	group: ["GXS_guyong_clear"],
	subSkill: {
		"clear": {
			charlotte: true,
			forced: true,
			popup: false,
			silent: true,
			trigger: {
				global: "roundStart"
			},
			content: function() {
				delete player.storage.GXS_guyong_used;
			}
		}
	}
},

"GXS_huzhu": {
	audio: "ext:华夏风云/audio/peiyin:2",
	trigger: {
		global: "useCardToTargeted"
	},
	filter: function(event, player) {
		if (event.card.name !== 'sha') return false;
		var target = event.target;
		return target !== player && target.isAlive() && target.hp === 1;
	},
	check: function(event, player) {
		if (get.attitude(player, event.target) <= 0) return false;
		return player.hp > 1 || player.countCards('h', 'shan') > 0;
	},
	logTarget: "target",
	content: function() {
		trigger.targets.remove(trigger.target);
		trigger.targets.add(player);
		if (trigger.getParent().triggeredTargets2) {
			trigger.getParent().triggeredTargets2.remove(trigger.target);
		}
		trigger.untrigger();
		
		player.line(trigger.target, 'green');
		game.log(player, '发动了【护主】，替', trigger.target, '成为此【杀】目标');
	}
},
                        
