           "GXS_quancai": {
	audio: "ext:华夏风云/audio/peiyin:2",
	enable: "phaseUse",
	filter: function(event, player) {
		if (player.countCards('h') < 2) return false;
		var used = player.storage.GXS_quancai_used || [];
		var redCount = player.countCards('h', function(card) {
			return get.color(card) == 'red';
		});
		var blackCount = player.countCards('h', function(card) {
			return get.color(card) == 'black';
		});
		
		if (!used.includes('wuzhong') && redCount >= 2 && event.filterCard({ name: 'wuzhong', isCard: true }, player, event)) return true;
		if (!used.includes('shunshou') && blackCount >= 2 && event.filterCard({ name: 'shunshou', isCard: true }, player, event)) return true;
		if (!used.includes('juedou') && redCount >= 1 && blackCount >= 1 && event.filterCard({ name: 'juedou', isCard: true }, player, event)) return true;
		return false;
	},
	chooseButton: {
		dialog: function(event, player) {
			var list = [];
			var used = player.storage.GXS_quancai_used || [];
			var redCount = player.countCards('h', function(card) {
				return get.color(card) == 'red';
			});
			var blackCount = player.countCards('h', function(card) {
				return get.color(card) == 'black';
			});

			if (!used.includes('wuzhong') && redCount >= 2) {
				list.push(['锦囊', '', 'wuzhong']);
			}
			if (!used.includes('shunshou') && blackCount >= 2) {
				list.push(['锦囊', '', 'shunshou']);
			}
			if (!used.includes('juedou') && redCount >= 1 && blackCount >= 1) {
				list.push(['锦囊', '', 'juedou']);
			}
			return ui.create.dialog('全才：请选择要转化的牌名', [list, 'vcard']);
		},
		filter: function(button, player) {
			return _status.event.getParent().filterCard({ name: button.link[2], isCard: true }, player, _status.event.getParent());
		},
		check: function(button) {
			var name = button.link[2];
			if (name == 'wuzhong') return 10;
			if (name == 'shunshou') return 8;
			if (name == 'juedou') return 6;
			return 1;
		},
		backup: function(links, player) {
			var name = links[0][2];
			return {
				audio: "GXS_quancai",
				filterCard: function(card, player) {
					if (get.position(card) != 'h') return false;
					if (name == 'wuzhong') {
						return get.color(card) == 'red';
					} else if (name == 'shunshou') {
						return get.color(card) == 'black';
					} else if (name == 'juedou') {
						if (!ui.selected.cards.length) return true;
						return get.color(card) != get.color(ui.selected.cards[0]);
					}
					return false;
				},
				selectCard: 2,
				position: "h",
				complexCard: true,
				viewAs: {
					name: name,
				},
				popname: true,
				onuse: function(result, player) {
					player.logSkill('GXS_quancai');
					if (!player.storage.GXS_quancai_used) {
						player.storage.GXS_quancai_used = [];
					}
					player.storage.GXS_quancai_used.push(name);
				},
				prompt: "选择2张手牌当作【" + get.translation(name) + "】使用",
			};
		},
		prompt: function(links, player) {
			return '将两张手牌当作【' + get.translation(links[0][2]) + '】使用';
		}
	},
	group: ["GXS_quancai_clear"],
	subSkill: {
		clear: {
			trigger: {
				player: ["phaseUseEnd", "phaseAfter"],
			},
			forced: true,
			popup: false,
			silent: true,
			content: function() {
				delete player.storage.GXS_quancai_used;
			}
		}
	},
	ai: {
		order: function(item, player) {
			var used = player.storage.GXS_quancai_used || [];
			var redCount = player.countCards('h', function(card) {
				return get.color(card) == 'red';
			});
			var blackCount = player.countCards('h', function(card) {
				return get.color(card) == 'black';
			});
			
			if (!used.includes('wuzhong') && redCount >= 2) return 9.5;
			if (!used.includes('shunshou') && blackCount >= 2) return 9;
			if (!used.includes('juedou') && redCount >= 1 && blackCount >= 1) return 5;
			return 1;
		},
		result: {
			player: 1
		}
	}
},
                        
