          //蔺相如              
                        
                        'GXS_guiqu': {
                            audio: "ext:华夏风云/audio/peiyin:2",
                            enable: 'phaseUse',
                            usable: 1,
                            filterTarget: lib.filter.notMe,
                            filter(event, player) {
                                return player.countCards('h') > 0;
                            },
                            content() {
                                'step 0'
                                var hs = player.getCards('h');
                                target.gain(hs, player, 'giveAuto');
                                'step 1'
                                var hs = target.getCards('h');
                                if (!hs.length) {
                                    event.finish();
                                    return;
                                }
                                hs.sort(function(a, b) {
                                    return get.value(b, player, 'raw') - get.value(a, player, 'raw');
                                });
                                target.chooseCard([1, hs.length], '展示至少一张手牌', true).set('ai', function(card) {
                                    var rand = _status.event.rand;
                                    var list = _status.event.list;
                                    if (_status.event.att) {
                                        if (ui.selected.cards.length >= Math.ceil(list.length / 2)) return 0;
                                        var value = get.value(card);
                                        if (_status.event.getParent().player.isHealthy()) {
                                            value += (get.tag(card, 'damage') ? 1.5 : 0) + (get.tag(card, 'draw') ? 2 : 0);
                                        }
                                        return value;
                                    }
                                    if (ui.selected.cards.length >= Math.floor(list.length / 2)) return 0;
                                    return (list.indexOf(card) % 2 == rand) ? 1 : 0;
                                }).set('rand', (Math.random() < 0.6) ? 1 : 0).set('list', hs).set('att', get.attitude(target, player) > 0);
                                'step 2'
                                target.showCards(result.cards);
                                event.cards1 = result.cards;
                                event.cards2 = target.getCards('h', function(card) {
                                    return !event.cards1.includes(card);
                                });
                                'step 3'
                                var choice;
                                var num1 = event.cards1.length;
                                var num2 = event.cards2.length;
                                if (get.attitude(target, player) > 0 && num1 >= num2) {
                                    choice = 0;
                                } else if (num1 == num2) {
                                    choice = (Math.random() < 0.45) ? 0 : 1;
                                } else if (num1 > num2) {
                                    if (num1 - num2 == 1) {
                                        choice = (Math.random() < 0.6) ? 0 : 1;
                                    } else {
                                        choice = 0;
                                    }
                                } else {
                                    if (num2 - num1 == 1) {
                                        choice = (Math.random() < 0.6) ? 1 : 0;
                                    } else {
                                        choice = 1;
                                    }
                                }
                                player.chooseControl(function(event, player) {
                                    return _status.event.choice;
                                }).set('choiceList', ['获得' + get.translation(target) + '展示的牌',
                                    '获得' + get.translation(target) + '未展示的牌'
                                ]).set('choice', choice);
                                'step 4'
                                if (result.index == 0) {
                                    player.gain(event.cards1, target, 'give');
                                } else {
                                    player.gain(event.cards2, target, 'giveAuto');
                                }
                            },
                            ai: {
                                expose: 0.1,
                                order: 3,
                                result: {
                                    target(player, target) {
                                        var maxval = 0;
                                        var hs = player.getCards('h');
                                        for (var i = 0; i < hs.length; i++) {
                                            maxval = Math.max(maxval, get.value(hs[i]));
                                        }
                                        var dh = target.countCards('h') - player.countCards('h');
                                        var att = get.attitude(player, target);
                                        if (target.hasSkill('qingjian')) return 0;
                                        if (dh <= 0) return 0;
                                        if (att > 0) return 0.1;
                                        if (maxval >= 8) return 0;
                                        if (att == 0) return 0.2;
                                        if (dh >= 3) return dh;
                                        if (dh == 2) {
                                            if (maxval <= 7) return dh;
                                        }
                                        if (maxval <= 6) return dh;
                                        return 0;
                                    }
                                }
                            },
                        },
                        
