                 GXS_nashi: {
    audio: "ext:华夏风云/audio/peiyin:2",
    trigger: {
        player: 'phaseBegin'
    },
    content() {
        'step 0'
        var skills = [];
        var map = {};
        var list;
        if (_status.characterlist) {
            list = _status.characterlist.slice(0);
        } else if (_status.connectMode) {
            list = get.charactersOL();
        } else {
            list = get.gainableCharacters();
        }
        var players = game.players.concat(game.dead);
        for (var i = 0; i < players.length; i++) {
            list.remove(players[i].name);
            list.remove(players[i].name1);
            list.remove(players[i].name2);
        }
        list.remove('GXS_mengchang');
        list = list.randomGets(3);
        var validList = [];
        for (var i = 0; i < list.length; i++) {
            var name = list[i];
            if (name.indexOf('zuoci') != -1 || name.indexOf('xushao') != -1) continue;
            var skills2 = lib.character[name][3];
            var gskill = skills2.randomGet();
            var sskill = [];
            sskill.push(gskill);
            for (var j of sskill) {
                var info = lib.skill[j];
                if (!info || info.hiddenSkill || info.dutySkill || info.charlotte || info.zhuSkill) continue;
                if (info.init || info.ai && (info.ai.combo || info.ai.notemp || info.ai.neg)) continue;
                validList.add(name);
                if (!map[name]) map[name] = [];
                map[name].push(j);
                skills.add(j);
            }
            if (skills.length > 2) break;
        }
        if (!skills.length) {
            event.finish();
        } else {
            player.chooseControl(skills).set('dialog', ['请选择要获得的技能', [validList, 'character']]).set('ai', function() {
                return 0
            });
        }
        'step 1'
        game.broadcastAll('closeDialog', event.videoId);
        player.addTempSkill(result.control, {
            player: "phaseBegin"
        });
    },
},

