                        GXS_zhigu: {
                            audio: "ext:华夏风云/audio/peiyin:2",
                            enable: "phaseUse",
                            filterTarget: true,
                            filterCard: true,
                            check(card) {
                                return 6 - get.value(card);
                            },
                            position: "he",
                            filter(event, player) {
                                var storage2 = player.getStorage('GXS_zhiguused');
                                return player.countCards('he') > 0 && (!storage2 || storage2.length < 3);
                            },
                            direct: true,
                            content() {
                                'step 0'
                                var list = [];
                                var choiceList = [
                                    '摸1张【杀】',
                                    '回合内下一张杀伤害+1',
                                    '回合内使用【杀】次数+1',
                                ];
                                var storage2 = player.getStorage('GXS_zhiguused');
                                for (var i = 0; i < 3; i++) {
                                    if (storage2.includes(i)) {
                                        choiceList[i] = ('<span style="text-decoration: line-through; opacity:0.5; ">' + choiceList[i] + '</span>');
                                    } else list.push('选项' + get.cnNumber(i + 1, true))
                                }
                                //list.push('cancel2');
                                player.chooseControl(list).set('prompt', get.prompt('GXS_zhigu')).set('choiceList', choiceList).set('ai', function() {
                                    var player = _status.event.player;
                                    var list = _status.event.controls.slice(0);
                                    var gett = function(choice) {
                                        //if(choice=='cancel2') return 0.1;
                                        var max = 0,
                                            func = {
                                                选项一(target) {
                                                    if (target.hasValueTarget({
                                                            name: 'sha'
                                                        }) && target.countCards('h', 'sha') == 0) max = Math.max(max, 4.3);
                                                },
                                                选项二(target) {
                                                    max = Math.max(max, player.getUseValue({
                                                        name: 'sha'
                                                    }));
                                                },
                                                选项三(target) {
                                                    var num = target.countCards('h', 'sha');
                                                    if (num > 1) max = Math.max(max, num);
                                                },
                                            } [choice];
                                        game.countPlayer(function(current) {
                                            if (current != target) func(current);
                                        });
                                        return max;
                                    };
                                    return list.sort(function(a, b) {
                                        return gett(b) - gett(a);
                                    })[0];
                                });
                                'step 1'
                                if (result.control != 'cancel2') {
                                    var index = ['选项一', '选项二', '选项三'].indexOf(result.control);
                                    event.index = index;
                                    player.logSkill('GXS_zhigu', target);
                                    player.getHistory('custom').push({
                                        GXS_zhigu: true
                                    });
                                    player.addTempSkill('GXS_zhiguused');
                                    if (!player.storage.GXS_zhiguused) player.storage.GXS_zhiguused = [];
                                    player.storage.GXS_zhiguused.push(event.index);
                                    switch (event.index) {
                                        case 0: {
                                            var card = get.cardPile(function(card) {
                                                return card.name == 'sha';
                                            });
                                            if (card) target.gain(card, 'gain2');
                                        };
                                        break;
                                        case 1:
                                            target.addTempSkill('GXSshaAddamage', {
                                                player: 'phaseEnd'
                                            });
                                            break;
                                        case 2:
                                            target.addTempSkill('GXSbuf_shaag', {
                                                player: 'phaseEnd'
                                            });
                                            break;
                                    }
                                }
                            },
                        },
                        GXS_zhiguused: {
                            onremove: true,
                        },
                        
              GXS_qingzui: {
    audio: "ext:华夏风云/audio/peiyin:2",
    trigger: {
        player: "phaseJieshuBegin",
    },
    filter: function(event, player) {
        var history = player.getHistory('custom', function(evt) {
            return evt.GXS_zhigu == true;
        });
        if (!history.length) return false;
        var shaDamage = player.getHistory('sourceDamage', function(evt) {
            return evt.card && evt.card.name == 'sha';
        });
        return !shaDamage.length;
    },
    content: function() {
        "step 0"
        var num = player.getHistory('custom', function(evt) {
            return evt.GXS_zhigu == true;
        }).length;
        event.num = num;
        // 自己先执行弃牌摸牌
        player.chooseToDiscard('h', num, true);
        player.draw(num);

        "step 1"
        // 判断其他角色计算与你的距离是否均大于1（即你装了+1马）
        if (!game.hasPlayer(function(current) {
            return current != player && get.distance(current, player) <= 1;
        })) {
            // 改为可选的：可以选择一名角色，也可以点取消
            player.chooseTarget("选择一名其他角色，令其执行请罪效果", function(card, player, target) {
                return target != player;
            }, false).set("ai", function(target) {
                return -get.attitude(player, target);
            });
        } else {
            event.finish();
        }

        "step 2"
        if (result && result.bool && result.targets && result.targets.length > 0) {
            var target = result.targets[0];
            player.logSkill('GXS_qingzui', target);
            target.chooseToDiscard('h', event.num, true);
            target.draw(event.num);
        }
    },
    skill_id: "GXS_qingzui",
    _priority: 0,
},

