GXS_sancai: {
    audio: "ext:华夏风云/audio/peiyin:2",
    trigger: {
        player: ["damageBegin2", "dying"],
    },
    forced: true,
    locked: false,
    filter: function (event, player) {
        if (event.name === "dying") {
            // 濒死时：必须由其他角色造成的，且标记≥3
            return event.source && event.source != player && player.countMark('GXS_jubao') >= 3;
        }
        // 造成伤害时：必须由其他角色造成的，且身上有标记
        // 若本次伤害会致死且标记≥3，不在此处处理，留给濒死分支
        if (event.source && event.source != player && player.countMark('GXS_jubao') >= 3 && (player.hp - event.num) < 1) {
            return false;
        }
        return event.source && event.source != player && player.countMark('GXS_jubao') > 0;
    },
    content: function () {
        "step 0"
        if (trigger.name === "dying") {
            // 濒死时：移除所有标记，回血至1点，双方摸等量牌
            var num = player.countMark('GXS_jubao');
            player.removeMark('GXS_jubao', num);
            player.recover(1 - player.hp);
            game.asyncDraw([player, trigger.source], num);
        } else {
            // 造成伤害时：移除1个标记，双方各摸1张牌
            player.removeMark('GXS_jubao', 1);
            game.asyncDraw([player, trigger.source], 1);
        }
        "step 1"
        // 台词部分
        if (trigger.source && trigger.source != player) {
            var says = ['匹夫犒天下之军，乱民也，宜诛之', '爆金币啦，老登！'];
            if (get.translation(trigger.source.name).indexOf('朱元璋') == -1) {
                trigger.source.say(says[1]);
            } else {
                trigger.source.say(says[0]);
            }
        }
    },
    skill_id: "GXS_sancai",
    _priority: 0,
},
                        
