                        "GXS_zhiqing": {
	audio: "ext:华夏风云/audio/peiyin:2",
	enable: "phaseUse",
	usable: 1, // 出牌阶段限 1 次
	filter: function(event, player) {
		// 核心：放开对自己手牌数的任何判定阻碍（至清自己没有手牌也可以主动发动！）
		return true;
	},
	filterTarget: function(card, player, target) {
		// 允许选择任意一名其他角色
		return target !== player;
	},
	selectTarget: 1,
	content: function() {
		'step 0'
		// 1. 分别读取你自己和目标角色当前手牌区里所有的“黑色卡牌”
		var player_cards = player.getCards('h', function(card) {
			return get.color(card) === 'black';
		});
		var target_cards = target.getCards('h', function(card) {
			return get.color(card) === 'black';
		});
		
		// 2. 分别记录双方各自需要弃置和摸回的卡牌数量
		event.player_num = player_cards.length;
		event.target_num = target_cards.length;
		
		// 3. 同时丢弃双方各自手里的黑色牌
		if (event.player_num > 0) {
			player.discard(player_cards);
		}
		if (event.target_num > 0) {
			target.discard(target_cards);
		}
		
		'step 1'
		// 4. 卡牌弃置完毕后，双端同时摸取等量的置换卡牌进入手牌，完成“至清”
		if (event.player_num > 0) {
			player.draw(event.player_num);
		}
		if (event.target_num > 0) {
			target.draw(event.target_num);
		}
	},
	ai: {
		order: 6, // 具有较高的出牌阶段优先级，方便 AI 进行手牌洗牌
		result: {
			player: function(player) {
				// 如果我们自己手里有黑色牌，则必定带来正向的洗牌收益
				return player.countCards('h', function(card) {
					return get.color(card) === 'black';
				}) > 0 ? 1 : 0.1;
			},
			target: function(player, target) {
				// AI 策略：优先选择手上有黑色牌的友军，帮队友进行大额的洗牌置换
				if (get.attitude(player, target) > 0) {
					var black_num = target.countCards('h', function(card) {
						return get.color(card) === 'black';
					});
					return black_num > 0 ? 1.2 : 0;
				}
				return 0;
			}
		}
	}
},
                        
            "GXS_sutan": {
    audio: "ext:华夏风云/audio/peiyin:2",
    trigger: {
        global: ["gainAfter", "loseAsyncAfter"]
    },
    forced: true,
    popup: false,
    filter: function(event, player) {
        return game.hasPlayer(function(current) {
            if (current === player) return false;
            if (_status.currentPhase === current) return false;
            return event.getg && event.getg(current).length > 0;
        });
    },
    content: function() {
        game.countPlayer(function(current) {
            if (current === player) return;
            if (_status.currentPhase === current) return;
            
            var num = trigger.getg(current).length;
            if (num > 0) {
                current.addSkill('GXS_sutan_mark');
                current.addMark('GXS_sutan_mark', num);
                game.log(current, '在回合外获得了', num, '张牌，累加了', num, '个“肃贪”印记');
            }
        });
    },
    group: ["GXS_sutan_trigger"],
    subSkill: {
        "mark": {
            charlotte: true,
            mark: true,
            marktext: "贪",
            intro: {
                content: function(storage, player) {
                    return "拥有 " + (player.countMark('GXS_sutan_mark') || 0) + " 个“肃贪”印记，在其回合开始时须弃置等量手牌";
                },
                markcount: function(storage, player) {
                    return player.countMark('GXS_sutan_mark') || 0;
                }
            }
        },
        "trigger": {
            charlotte: true,
            forced: true,
            popup: false,
            silent: true,
            trigger: {
                global: "phaseBegin"
            },
            filter: function(event, player) {
                var target = event.player;
                return target !== player && target.hasSkill('GXS_sutan_mark') && target.countMark('GXS_sutan_mark') > 0;
            },
            content: function() {
                'step 0'
                var target = trigger.player;
                event.target = target;
                
                var num = target.countMark('GXS_sutan_mark');
                event.num = num;
                
                // 关键清理步骤：先移除技能，再清零标记，确保界面不残留
                target.removeSkill('GXS_sutan_mark');
                target.setMark('GXS_sutan_mark', 0);
                target.unmarkSkill('GXS_sutan_mark');
                
                // 随机弃置其 num 张手牌
                var cards = target.getCards('h');
                if (cards.length > 0) {
                    var discardCards = cards.randomGets(Math.min(num, cards.length));
                    target.discard(discardCards);
                    event.discarded = discardCards.length;
                } else {
                    event.discarded = 0;
                }
                
                'step 1'
                if (event.discarded < event.num) {
                    player.chooseBool('是否令 ' + get.translation(event.target) + ' 流失 1 点体力？').set('ai', function() {
                        return get.attitude(player, event.target) < 0;
                    });
                } else {
                    event.finish();
                }
                
                'step 2'
                if (result.bool) {
                    event.target.loseHp();
                    game.log(player, '触发了【肃贪】惩罚，令', event.target, '流失了 1 点体力');
                }
            }
        }
    }
},
                        
