                        "GXS_zhuji": {
	audio: "ext:华夏风云/audio/peiyin:2",
	enable: ["chooseToUse", "chooseToRespond"],
	viewAs: { name: "sha" },
	filterCard: true,
	position: "h",
	selectCard: -1, // 选中所有手牌进行转化
	filter(event, player) {
		var hs = player.getCards("h");
		if (!hs.length) return false;
		for (var i = 0; i < hs.length; i++) {
			var mod2 = game.checkMod(hs[i], player, "unchanged", "cardEnabled2", player);
			if (mod2 === false) return false;
		}
		return event.filterCard(get.autoViewAs({ name: "sha" }, hs));
	},
	prompt: "将所有手牌当【杀】使用或打出",
	group: ["GXS_zhuji_mark", "GXS_zhuji_discard"],
	subSkill: {
		"mark": {
			charlotte: true,
			trigger: {
				player: "useCard1"
			},
			forced: true,
			popup: false,
			silent: true,
			filter: function(event, player) {
				return event.skill === 'GXS_zhuji';
			},
			content: function() {
				if (!trigger.card.storage) trigger.card.storage = {};
				trigger.card.storage.GXS_zhuji = true;
			}
		},
		"discard": {
			charlotte: true,
			trigger: {
				source: "damageEnd"
			},
			forced: true,
			popup: false,
			filter: function(event, player) {
				return event.card && event.card.storage && event.card.storage.GXS_zhuji && event.player && event.player.countCards('h') > 0;
			},
			content: function() {
				var target = trigger.player;
				player.logSkill('GXS_zhuji', target);
				target.discard(target.getCards('h'));
				game.log(player, '触发了【筑击】效果：弃置了', target, '的所有手牌');
			}
		}
	},
	ai: {
		order: 5,
		respondSha: true,
		skillTagFilter(player, tag) {
			if (tag === "respondSha") {
				return player.countCards('h') > 0;
			}
		},
		result: {
			player(player, target) {
				let cards = player.getCards("h");
				return get.value(cards, player) * Math.sqrt(cards.length) <= 12;
			}
		}
	}
},

"GXS_lige": {
	audio: "ext:华夏风云/audio/peiyin:2",
	trigger: {
		global: "phaseEnd" // 任意角色回合结束时
	},
	filter: function(event, player) {
		return player.countCards('h') === 0; // 你没有手牌时
	},
	content: function() {
		'step 0'
		var discardPile = Array.from(ui.discardPile.childNodes);
		if (!discardPile.length) {
			event.finish();
			return;
		}
		// 系统在后台从弃牌堆直接随机选择至多 3 张牌
		var randomCards = discardPile.randomGets(3);
		event.randomCards = randomCards;
		
		// 呼出选择对话框
		player.chooseButton([
			"离歌：请选择一张卡牌交给任意角色",
			randomCards
		], true).set('ai', function(button) {
			return get.value(button.link, player);
		});
		
		'step 1'
		if (result.bool && result.links && result.links.length > 0) {
			event.chosenCard = result.links[0];
			// 挑选交给的任意目标角色
			player.chooseTarget("离歌：选择一名角色获得 " + get.translation(event.chosenCard), true)
				.set('ai', function(target) {
					var player = get.player();
					var card = _status.event.getParent().chosenCard;
					return get.value(card, target) * get.attitude(player, target);
				});
		} else {
			event.finish();
		}
		
		'step 2'
		if (result.bool) {
			var target = result.targets[0];
			player.line(target, 'green');
			// 直接将选择的弃牌移动进目标的手牌中
			target.gain(event.chosenCard, 'gain2');
			game.log(player, '发动【离歌】，将弃牌堆中的', event.chosenCard, '交给了', target);
		}
	},
	ai: {
		order: 6,
		result: {
			player: 1
		}
	}
},
                        
