             GXS_shenwu: {
                            audio: "ext:华夏风云/audio/peiyin:2",
                            enable: 'phaseUse',
                            usable: 1,
                            filter(event, player) {
                                return player.countCards("h");
                            },
                            check(event, player) {
                                const colors = player
                                    .getCards("h")
                                    .map(card => get.color(card, player))
                                    .toUniqued();
                                for (let color of colors) {
                                    if (lib.skill.GXS_shenwu.getVal(color, player) > 0) {
                                        return true;
                                    }
                                }
                                return false;
                            },
                            getVal(color, player) {
                                let val = 0,
                                    cards = player.getCards("h", {
                                        color: color
                                    });
                                val -= cards.length;
                                if (color == "black") {
                                    val += cards.reduce((sum, current) => {
                                        return sum + get.value(current, player);
                                    }, 0);
                                } else if (color == "red") {
                                    val += cards.reduce((sum, current) => {
                                        return sum + get.value(current, player);
                                    }, 0);
                                }
                                return val;
                            },
                            async content(event, trigger, player) {
                                let colors = player
                                    .getCards("h")
                                    .map(card => get.color(card, player))
                                    .toUniqued();
                                if (!colors.length) {
                                    return;
                                }
                                colors.sort((a, b) => lib.skill.GXS_shenwu.getVal(b, player) - lib.skill.GXS_shenwu.getVal(a, player));
                                const result = await player
                                    .chooseControl(colors)
                                    .set("prompt", "选择要给的一种颜色的所有手牌")
                                    .set("resultC", colors[0])
                                    .set("ai", () => {
                                        return get.event("resultC");
                                    })
                                    .forResult();
                                if (result.control) {
                                    const color = result.control,
                                        cards = player.getCards("h").filter(card => get.color(card, player) == color);
                                    if (cards.length) {
                                        const result2 = await player
                                            .chooseTarget("选择神武目标", true, (card, player, target) => {
                                                return target != player;
                                            })
                                            .set("ai", target => {
                                                const player = get.player();
                                                return -get.attitude(player, target);
                                            })
                                            .forResult();
                                        if (!result2.bool) {
                                            return;
                                        }
                                        const target = result2.targets[0];
                                        await player.give(cards, target);
                                        if (color == "black") {
                                            if (target.getCards('h', {
                                                    color: 'red'
                                                }).length) await player.gain(target.getCards('h', {
                                                color: 'red'
                                            }));
                                        } else {
                                            if (target.getCards('h', {
                                                    color: 'black'
                                                }).length) await player.gain(target.getCards('h', {
                                                color: 'black'
                                            }));
                                        }
                                    }
                                }
                            },
                            ai: {
                                order: 3,
                                result: {
                                    target(player, target) {
                                        if (lib.skill.GXS_shenwu.getVal('black', player) - lib.skill.GXS_shenwu.getVal('red', player) > 0) return -1;
                                        return 0;
                                    }
                                }
                            }
                        },                         
                        
