              "yxs_zhudao": {
	audio: "ext:华夏风云/audio/peiyin:2",
	enable: "phaseUse",
	usable: 1, // 出牌阶段限 1 次
	position: "h", // 只能弃置手牌
	filterCard: true, // 允许点选手牌
	selectCard: [1, 3], // 限制弃置 1 至 3 张手牌
	prompt: "请选择弃置 1 至 3 张手牌以发动【主道】（将摸取双倍手牌并记录总点数）",
	// 极智 AI 选牌策略：由于需要弃置牌来换取点数池，AI 优先挑选“点数极大、价值极低”的牌进行弃置
	check: function(card) {
		var player = _status.event.player;
		return get.number(card) * 2 - get.value(card, player);
	},
	filter: function(event, player) {
		return player.countCards('h') > 0;
	},
	content: function() {
		'step 0'
		var discardNum = event.cards.length;
		
		// 计算所弃置卡牌的点数之和
		var sum = 0;
		for (var i = 0; i < event.cards.length; i++) {
			sum += get.number(event.cards[i]);
		}
		
		// 获得双倍数量的摸牌
		player.draw(discardNum * 2);
		
		// 将总点数存入存储区，并加载、标亮头像旁的“道”字角标
		player.storage.yxs_zhudao_sum = sum;
		player.addSkill('yxs_zhudao_mark');
		player.markSkill('yxs_zhudao_mark');
		
		game.log(player, '发动了【主道】，弃置了', discardNum, '张手牌并摸牌', discardNum * 2, '张，当前“主道”点数池为', sum, '点');
	},
	subSkill: {
		// 点数统计与强制结束出牌阶段的标记状态技（完全静默运行）
		"mark": {
			charlotte: true,
			mark: true,
			marktext: "道",
			intro: {
				content: "当前剩余“主道”点数：#",
				// 标记旁直接展示当前的剩余点数数字
				markcount: function(storage, player) {
					return player.storage.yxs_zhudao_sum || 0;
				}
			},
			// 监听：你在你自己的回合使用牌结算后，以及你的出牌阶段结束时
			trigger: {
				player: "useCardAfter",
				global: "phaseUseEnd"
			},
			forced: true,
			popup: false,
			filter: function(event, player, name) {
				if (name === "useCardAfter") {
					// 必须是在你自己的出牌阶段内使用卡牌，且“主道”点数尚未扣减至零
					return player.isPhaseUsing() && player.storage.yxs_zhudao_sum > 0;
				}
				if (name === "phaseUseEnd") {
					// 当你自己的出牌阶段结束时，无条件触发清除
					return event.player === player;
				}
				return false;
			},
			content: function() {
				if (event.triggername === "useCardAfter") {
					// 获取当前所使用卡牌的点数，并从你当前的点数池中扣除
					var cardPoint = get.number(trigger.card) || 0;
					player.storage.yxs_zhudao_sum -= cardPoint;
					
					game.log(player, '使用卡牌', trigger.card, '（点数为 ' + cardPoint + '），“主道”点数下降至', player.storage.yxs_zhudao_sum);
					
					// 判定：若点数池已被扣尽（即使用牌的总点数已经大于等于弃置牌的总点数）
					if (player.storage.yxs_zhudao_sum <= 0) {
						// A. 直接调用底层接口，瞬间中止并强制结束当前的出牌阶段
						var evt = _status.event.getParent('phaseUse');
						if (evt) {
							evt.finish();
						}
						
						// B. 后台安全注销状态和存储
						player.removeSkill('yxs_zhudao_mark');
						delete player.storage.yxs_zhudao_sum;
						game.log(player, '由于使用牌的点数超过了弃置牌的总点数，【主道】强制结束了其出牌阶段');
					} else {
						// 否则在不结束的情况下，实时刷新小角标的剩余点数数字
						player.updateMark('yxs_zhudao_mark');
					}
				} else if (event.triggername === "phaseUseEnd") {
					// 回合正常结束时，后台静默卸载
					player.removeSkill('yxs_zhudao_mark');
					delete player.storage.yxs_zhudao_sum;
				}
			}
		}
	}
},
                        
            //平阳公主            
                        
