          GXS_bagua: {
    trigger: {
        global: "phaseBefore",
    },
    filter(event, player) {
        return game.hasPlayer(current => current != player) && !game.hasPlayer(current => current.hasMark('GXS_bagua_mark'));
    },
    audio: "ext:华夏风云/audio/peiyin:2",
    check(event, player) {
        return true;
    },
    content() {
        "step 0"
        player.chooseTarget("是否发动【八卦】？选择一名角色获得八卦标记", lib.translate.GXS_bagua_info, function(card, player, target) {
            return target != player && !target.storage.GXS_bagua_mark
        }).set("ai", function(target) {
            let att = get.attitude(_status.event.player, target);
            if (att < 0) {
                return 20 - att;
            }
            if (att == 0) {
                return 5 + Math.random();
            }
            return 10 - att;
        });

        "step 1"
        if (result.bool && result.targets && result.targets[0]) {
            var target = result.targets[0];
            target.storage.GXS_bagua_mark = true;
            target.markSkill("GXS_bagua_mark", null, null, true);
            game.log(player, "发动了", "#g【八卦】", "，令", target, "获得八卦标记");
        }
    },
    group: 'GXS_bagua_liuli',
    subSkill: {
        liuli: {
            trigger: {
                target: "useCardToTarget"
            },
            filter(event, player) {
                if (event.card.name != "sha") {
                    return false;
                }
                if (player.countCards("he") == 0) {
                    return false;
                }
                var source = event.player;
                if (!source || !source.storage) return false;
                if (source.storage.GXS_bagua_mark) return false;
                return game.hasPlayer(current => {
                    return current.storage.GXS_bagua_mark && current != player && lib.filter.targetEnabled(event.card, event.player, current);
                });
            },
            check(event, player) {
                return true;
            },
            content() {
                "step 0"
                player.chooseCardTarget({
                    position: "he",
                    filterCard: lib.filter.cardDiscardable,
                    filterTarget: (card, player, target) => {
                        return target.storage.GXS_bagua_mark;
                    },
                    ai1: card => {
                        let val = get.unuseful(card) + 9;
                        if (get.name(card) == "sha") val += 5;
                        return val;
                    },
                    ai2: target => {
                        const player = get.player();
                        let att = get.attitude(player, target);
                        if (att < 0) return 20 - att;
                        if (att == 0) return 10;
                        return 5;
                    },
                    prompt: "是否发动【八卦】？",
                    prompt2: "弃置一张牌，将此【杀】转移给有八卦的角色",
                    source: trigger.player,
                    card: trigger.card,
                }).setHiddenSkill(event.name.slice(0, -5));

                "step 1"
                if (result.bool) {
                    var target = result.targets[0];
                    player.discard(result.cards);
                    var evt = trigger.getParent();
                    evt.triggeredTargets2.remove(player);
                    evt.targets.remove(player);
                    evt.targets.push(target);
                    game.log(player, "发动了", "#g【八卦】", "，将【杀】转移给", target);
                }
            },
        }
    }
},
