          //吴用
          
          GXS_shensuan: {
                            audio: "ext:华夏风云/audio/peiyin:2",
                            trigger: {
                                player: "phaseJieshuBegin",
                            },
                            frequent: true,
                            filter(event, player) {
                                return player.countCards('h') > 0;
                            },
                            content() {
                                "step 0";
                                player.chooseToDiscard('是否开始求导？', function(card) {
                                    return true;
                                })
                                "step 1";
                                if (result.bool) {
                                    event.num = result.cards[0].number ?? 0;
                                    event.num2 = 0;
                                    event.cards = [];
                                } else event.finish();
                                "step 2";
                                var next = player.judge('正在LogIng....', function(card) {
                                    if (event.num2 + card.number < event.num) {
                                        return 1;
                                    }
                                    return -1;
                                });
                                next.judge2 = function(result) {
                                    return result.bool;
                                };
                                if (get.mode() != "guozhan" && !player.hasSkillTag("rejudge")) {
                                    next.set("callback", function() {
                                        if (get.position(card, true) == "o") {
                                            player.gain(card, "gain2");
                                        }
                                    });
                                } else {
                                    next.set("callback", function() {
                                        event.getParent().orderingCards.remove(card);
                                    });
                                }
                                "step 3";
                                if (result.judge > 0) {
                                    event.cards.push(result.card);
                                    event.num2 += result.card.number;
                                } else {
                                    for (var i = 0; i < event.cards.length; i++) {
                                        if (get.position(event.cards[i], true) != "o") {
                                            event.cards.splice(i, 1);
                                            i--;
                                        }
                                    }
                                    if (event.cards.length) {
                                        player.gain(event.cards, "gain2");
                                    }
                                    event.finish();
                                }
                                "step 4";
                                if (event.num2 < event.num) {
                                    event.goto(2);
                                } else {
                                    if (event.cards.length) {
                                        player.gain(event.cards, "gain2");
                                    }
                                }
                            },
                        },
                        
          "ztjx_tianji": {
    audio: "ext:华夏风云/audio/peiyin:2",
    trigger: {
        player: ["useCard", "respond"],
    },
    forced: true,
    locked: true,
    filter: function (event, player) {
        return true;
    },
    content: function () {
        "step 0"
        var num = get.number(trigger.card);
        var current = Number(player.getStorage("ztjx_tianji")) || 0;
        current = current + num;
        player.setStorage("ztjx_tianji", current);
        player.markSkill("ztjx_tianji");
        if (current < 13) {
            event.finish();
            return;
        }
        player.logSkill("ztjx_tianji");
        "step 1"
        event.card1 = get.cards(1);
        event.card2 = get.bottomCards(1);
        
        if (!event.card1 || !event.card1.length || !event.card2 || !event.card2.length) {
            event.finish();
            return;
        }
        var dialog = [
            '天机：选择获得其中一张牌',
            '<div class="text center">牌堆顶</div>',
            event.card1,
            '<div class="text center">牌堆底</div>',
            event.card2
        ];
        player.chooseButton(dialog, true).set('ai', function(button) {
            return get.value(button.link, player);
        });
        "step 2"
        if (result && result.bool && result.links) {
            var chosen = result.links[0];
            if (chosen === event.card1[0]) {
                ui.cardPile.appendChild(event.card2[0]);
            } else {
                ui.cardPile.insertBefore(event.card1[0], ui.cardPile.firstChild);
            }
            game.updateRoundNumber();
            player.gain(chosen, 'draw', 'log');
            var current = Number(player.getStorage("ztjx_tianji")) || 0;
            current = current - 13;
            player.setStorage("ztjx_tianji", current);
            player.markSkill("ztjx_tianji");
        }
    },
    intro: {
        markcount: function (storage, player) {
            return Number(player.getStorage("ztjx_tianji")) || 0;
        },
        content: function (storage, player) {
            var current = Number(player.getStorage("ztjx_tianji")) || 0;
            return "累计点数：" + current + "/13";
        },
    },
    ai: {
        threaten: 0.5,
    },
    skill_id: "ztjx_tianji",
    _priority: 0,
},
                        
