            "GXS_vxtianxiang": {
	audio: "ext:华夏风云/audio/peiyin:3",
	trigger: {
		global: "judgeFixing"
	},
	filter: function(event, player) {
		return event.result;
	},
	check: function(event, player) {
		if (get.type(event.card) != 'delay' && event.player == player) return false;
		if (get.attitude(player, event.player) >= 0 && get.type(event.card) != 'delay') return false;
		if (get.attitude(player, event.player) <= 0 && get.type(event.card) == 'delay') return false;
		return true;
	},
	content: function() {
	
		var card = trigger.result.card;
		if (card && get.suit(card) === 'diamond') {
			player.gain(card, 'gain2');
		}
		
		if (trigger.result) {
			trigger.result.bool = false;
			trigger.result.card = null;
		}
		
		var evt = trigger.getParent();
		if (evt.name == "phaseJudge") {
			evt.excluded = true; 
		} else {
	
			delete evt.callback;
			delete evt.onresult;
			
			evt.cancel(); 
			
			var parentEvt = evt.getParent();
			if (parentEvt && parentEvt.name && parentEvt.name.indexOf("pre_") === 0) {
				parentEvt.cancel();
			}
			
			var nexts = evt.next.slice();
			for (var next of nexts) {
				if (next.name == "judgeCallback") {
					evt.next.remove(next);
				}
			}
			
			var evts = game.getGlobalHistory("cardMove", function (e) {
				return e.getParent(2) == evt;
			});
			var cards = [];
			for (var i = evts.length - 1; i >= 0; i--) {
				var moveEvt = evts[i];
				for (var c of moveEvt.cards) {
					if (get.position(c, true) == "o") {
						cards.push(c);
					}
				}
			}

			if (evt.orderingCards) {
				evt.orderingCards.addArray(cards);
			}
		}
		
		if (trigger.card && get.type(trigger.card) == 'delay') {
			trigger.player.addJudge(trigger.card);
		}
		
		game.log(player, '发动了【天香】，取消了对', trigger.player, '的判定');
	}
},

