            //李贤
            
            GXS_vxweiya: {
    audio: "ext:华夏风云/audio/peiyin:2",
    enable: "phaseUse",
    usable: 1,
    filter: function(event, player) {
        // 需要有其他有牌的角色
        return game.hasPlayer(function(current) {
            return current != player && current.countCards('h') > 0;
        });
    },
    filterTarget: function(card, player, target) {
        // 只能选择其他有牌的角色
        return target != player && target.countCards('h') > 0;
    },
    content: function() {
        "step 0"
        // 选中的目标A（被命令出杀的角色）
        var targetA = target;
        event.targetA = targetA;
        
        // 选择目标A攻击范围内的另一名角色B
        var candidates = game.filterPlayer(function(current) {
            return current != targetA && targetA.inRange(current);
        });
        if (candidates.length === 0) {
            event.finish();
            return;
        }
        player.chooseTarget("选择 " + get.translation(targetA) + " 攻击范围内的一名角色", function(card, player, target) {
            return target != targetA && targetA.inRange(target);
        }).set('ai', function(target) {
            // 简单的AI：尽量选择敌人，或自己（为了摸牌）
            var att = get.attitude(player, target);
            if (target == player) return 10; // 选自己可能摸牌
            return -att;
        });
        "step 1"
        if (!result.bool) {
            event.finish();
            return;
        }
        var targetB = result.targets[0];
        event.targetB = targetB;
        
        // 让目标A选择是否对B使用一张杀
        var next = event.targetA.chooseToUse({
            name: 'sha'
        }, targetB, "威压：是否对 " + get.translation(targetB) + " 使用一张【杀】？");
        next.set('ai', function() {
            // 如果B是敌人，更可能出杀；否则可能不出
            var att = get.attitude(event.targetA, targetB);
            if (att < 0) return 1;
            if (att > 0) return 0;
            return 0.5;
        });
        "step 2"
        if (result && result.bool) {
            // 目标A出了杀
            if (event.targetB == player) {
                // 指定的目标是自己，摸一张牌
                player.logSkill('GXS_vxweiya', event.targetA);
                player.draw();
            } else {
                // 出了杀但目标不是自己，目标A交给玩家一张牌
                player.logSkill('GXS_vxweiya', event.targetA);
                var cards = event.targetA.getCards('he');
                if (cards.length) {
                    event.targetA.chooseCard('he', "威压：请交给 " + get.translation(player) + " 一张牌", true).set('ai', function(card) {
                        return -get.value(card); // 尽量给价值低的牌
                    });
                } else {
                    event.finish();
                }
            }
        } else {
            // 目标A没有出杀，交给玩家一张牌
            player.logSkill('GXS_vxweiya', event.targetA);
            var cards = event.targetA.getCards('he');
            if (cards.length) {
                event.targetA.chooseCard('he', "威压：请交给 " + get.translation(player) + " 一张牌", true).set('ai', function(card) {
                    return -get.value(card);
                });
            } else {
                event.finish();
            }
        }
        "step 3"
        if (result && result.cards && result.cards.length) {
            player.gain(result.cards, event.targetA, 'giveAuto');
            player.$gain2(result.cards);
        }
    },
    ai: {
        order: 7,
        result: {
            player: function(player) {
                // 如果有敌人且自己有杀的机会，可以考虑发动
                return 1;
            }
        }
    }
},

