			yxs_xianyi: {
	audio: "ext:华夏风云/audio/peiyin:2",
	enable: ["chooseToUse", "chooseToRespond", "phaseUse"],
	usable: 1,
	hiddenCard: function (player, name) {
		if (get.type(name) == 'basic' && lib.inpile.contains(name)) return true;
	},
	filter: function (event, player) {
		if (event.responded || event.yxs_xianyi) return false;
		for (var i of lib.inpile) {
			if (get.type(i) == 'basic' && event.filterCard({ name: i }, player, event)) return true;
		}
		return true;
	},
	delay: false,
	content: function () {
		'step 0'
		var evt = event.getParent(2);
		evt.set('yxs_xianyi', true);
		var x = player.getDamagedHp() + 2;
		var len = ui.cardPile.childNodes.length;
		var cards = [];
		for (var i = 0; i < Math.min(x, len); i++) {
			cards.push(ui.cardPile.childNodes[len - 1 - i]);
		}
		var aozhan = player.hasSkill('aozhan');
		
		event.cards = cards;
		event.usableCards = cards.filter(function (card) {
			if (aozhan && card.name == 'tao') {
				return evt.filterCard({
					name: 'sha', isCard: true, cards: [card],
				}, evt.player, evt) || evt.filterCard({
					name: 'shan', isCard: true, cards: [card],
				}, evt.player, evt);
			}
			return evt.filterCard(card, evt.player, evt);
		});
		
		player.chooseButton(['先义：选择要' + (evt.name == 'chooseToUse' ? '使用' : '打出') + '的牌', cards]).set('filterButton', function (button) {
			return _status.event.cards.contains(button.link);
		}).set('cards', event.cards).set('ai', function (button) {
			var evt = _status.event.getParent(3);
			if (evt && _status.event.usableCards.contains(button.link)) {
				var tmp = _status.event;
				_status.event = evt;
				var result = (evt.ai || event.ai1)(button.link, _status.event.player, evt);
				_status.event = tmp;
				return result;
			}
			return 0;
		});
		
		'step 1'
		var evt = event.getParent(2);
		if (result.bool && result.links && result.links.length) {
			var card = result.links[0];
			var is_usable = event.usableCards.contains(card);
			
			if (!is_usable) {
				game.cardsDiscard(card);
				player.$throw(card, 1000);
				game.log(player, '通过【先义】选择的', card, '无法使用，置入弃牌堆');
			} else {
				var name = card.name;
				var aozhan = (player.hasSkill('aozhan') && name == 'tao');
				if (aozhan) {
					name = evt.filterCard({
						name: 'sha', isCard: true, cards: [card],
					}, evt.player, evt) ? 'sha' : 'shan';
				}
				if (evt.name == 'chooseToUse') {
					game.broadcastAll(function (result, name) {
						lib.skill.yxs_xianyi_backup.viewAs = { name: name, cards: [result], isCard: true };
						lib.skill.yxs_xianyi_backup.prompt = '选择' + get.translation(result) + '的目标';
					}, card, name);
					evt.set('_backupevent', 'yxs_xianyi_backup');
					evt.backup('yxs_xianyi_backup');
				} else {
					delete evt.result.skill;
					delete evt.result.used;
					evt.result.card = get.autoViewAs(card);
					if (aozhan) evt.result.card.name = name;
					evt.result.cards = [card];
					evt.redo();
					return;
				}
			}
		}
		evt.goto(0);
	},
	ai: {
		effect: {
			target: function (card, player, target, effect) {
				if (get.tag(card, 'respondShan')) return 0.7;
				if (get.tag(card, 'respondSha')) return 0.7;
				if (get.tag(card, 'respondTao')) return 1;
			}
		},
		order: 7,
		respondShan: true,
		respondSha: true,
		respondTao: true,
		result: {
			player: function (player) {
				if (_status.event.dying) return get.attitude(player, _status.event.dying);
				return 3;
			}
		}
	}
},
