			yyyifu: {
	audio: "ext:华夏风云/audio/peiyin:2",
	frequent: true,
	trigger: {
		player: "phaseBegin",
	},
	filter(event, player) {
		return game.hasPlayer((current) => {
			return current !== player && get.distance(player, current) <= 1;
		});
	},
	async content(event, trigger, player) {
		const targets = game
			.filterPlayer((target) => {
				return target !== player && get.distance(player, target) <= 1;
			})
			.sortBySeat();

		player.logSkill("yyyifu", targets);

		for (const target of targets) {
			if (!target.isIn() || !target.countCards("he")) {
				if (target.isIn()) {
					await player.useCard({ name: "sha", isCard: false }, target, false);
				}
				continue;
			}

			const result = await target
				.chooseCard("he", `是否交给${get.translation(player)}一张牌？`)
				.set("ai", (card) => {
					if (_status.event.goon) {
						return 7 - get.value(card);
					}
					return 0;
				})
				.set("goon", get.attitude(target, player) > 1)
				.forResult();

			if (result?.bool && result.cards?.length) {
				await target.give(result.cards, player, true);

				for (const card of result.cards) {
					if (get.color(card) === "red") {
						target.addSkill("yyyifuhong");
					} else if (get.color(card) === "black") {
						target.addSkill("yyyifuhei");
					}
				}

				player.addTempSkill("yyyifu3", { global: "phaseEnd" });
			} else if (target.isIn()) {
				await player.useCard({ name: "sha", isCard: false }, target, false);
			}
		}
	},
	group: "yyyifu2",
},

