			//乐毅
			
			yxs_cuilian: {
    audio: "ext:华夏风云/audio/peiyin:2",
    trigger: {
      player: "useCard",
      global: "phaseEnd", // 回合结束清空【疑】印记
    },
    filter(event, player) {
      if (event.name === "phase") {
        return player.countMark("yxs_cuilian_yi") > 0 || Boolean(player.storage.yxs_cuilian_last);
      }
      // 达到5层后本轮不可再发动
      if (player.hasSkill("yxs_cuilian_round_disabled")) return false;
      return true;
    },
    forced: true,
    async content(event, trigger, player) {
      // 1. 回合结束：清空【疑】与记录
      if (trigger.name === "phase") {
        player.removeMark("yxs_cuilian_yi", player.countMark("yxs_cuilian_yi"));
        delete player.storage.yxs_cuilian_last;
        return;
      }

      const card = trigger.card;
      const currentAttr = {
        type: get.type2(card, player),
        suit: get.suit(card, player),
        number: get.number(card, player),
      };

      const lastAttr = player.storage.yxs_cuilian_last;
      // 记录本次使用的卡牌属性供下次对比
      player.storage.yxs_cuilian_last = currentAttr;

      // 如果是本回合使用的第一张牌，仅记录不结算对比
      if (!lastAttr) return;

      // 2. 对比卡牌属性（类型 / 花色 / 点数）
      let sameCount = 0;
      if (currentAttr.type === lastAttr.type) sameCount++;
      if (currentAttr.suit === lastAttr.suit) sameCount++;
      if (currentAttr.number === lastAttr.number) sameCount++;
      const diffCount = 3 - sameCount;

      game.log(player, "触发【摧连】：", sameCount, "项相同，", diffCount, "项不同");

      // 3. 获得【疑】印记
      if (diffCount > 0) {
        player.addMark("yxs_cuilian_yi", diffCount);
        // 达到5层及以上，本轮封印
        if (player.countMark("yxs_cuilian_yi") >= 5) {
          game.log(player, "【疑】印记达到5层，本轮【摧连】失效");
          player.addTempSkill("yxs_cuilian_round_disabled", { player: "roundAfter" });
        }
      }

      // 4. 相同项摸牌
      if (sameCount > 0) {
        await player.draw(sameCount);
      }
    },
    subSkill: {
      round_disabled: { charlotte: true },
    },
    intro: {
      content: "当前拥有 # 层【疑】印记（达到5层时本轮无法发动）",
    },
  },
			
