           //荀彧
           
           "yxs_quhu": {
	audio: "ext:华夏风云/audio/peiyin:2",
	enable: "phaseUse",
	usable: 1,
	log: false,
	filter: function(event, player) {
		if (game.players.length < 2) return false;
		var maxHand = Math.max(...game.players.map(function(p) { return p.countCards('h'); }));
		var maxHp = Math.max(...game.players.map(function(p) { return p.hp; }));
		var list1 = game.players.filter(function(p) { return p.countCards('h') === maxHand; });
		var list2 = game.players.filter(function(p) { return p.hp === maxHp; });
		return !(list1.length === 1 && list2.length === 1 && list1[0] === list2[0]);
	},
	content: function() {
		'step 0'
		var maxHand = Math.max(...game.players.map(function(p) { return p.countCards('h'); }));
		var maxHp = Math.max(...game.players.map(function(p) { return p.hp; }));
		event.maxHand = maxHand;
		event.maxHp = maxHp;
		event.list2 = game.players.filter(function(p) { return p.hp === maxHp; });
		
		player.chooseTarget('驱虎：选择一名手牌数最多的角色（出杀者）', function(card, player, target) {
			if (target.countCards('h') !== event.maxHand) return false;
			if (event.list2.length === 1 && event.list2[0] === target) return false;
			return true;
		}).set('ai', function(target) {
			var att = get.attitude(_status.event.player, target);
			if (att < 0) return 10 - att;
			return 1;
		});
		
		'step 1'
		if (result.bool && result.targets && result.targets.length) {
			event.target1 = result.targets[0];
			player.chooseTarget('驱虎：选择一名体力值最多的角色（被杀者，不能与先选者重合）', function(card, player, target) {
				return target !== event.target1 && target.hp === event.maxHp;
			}).set('ai', function(target) {
				var att = get.attitude(_status.event.player, target);
				if (att < 0) return 12 - att;
				return 0.1;
			});
		} else {
			event.finish();
		}
		
		'step 2'
		if (result.bool && result.targets && result.targets.length) {
			event.target2 = result.targets[0];
			player.logSkill('yxs_quhu', [event.target1, event.target2]);
			game.log(player, '发动【驱虎】，令', event.target1, '对', event.target2, '使用一张【杀】');
			
			event.target1.chooseToUse({
				filterCard: function(card, player) {
					return get.name(card, player) === 'sha';
				},
				filterTarget: function(card, player, target) {
					return target === event.target2;
				},
				addCount: false,
				prompt: '驱虎：请对 ' + get.translation(event.target2) + ' 使用一张【杀】（不计入次数），否则其视为对你使用一张【杀】',
				ai1: function(card) {
					return 6 - get.value(card);
				}
			});
		} else {
			event.finish();
		}
		
		'step 3'
		if (!result.bool) {
			game.log(event.target1, '未对', event.target2, '使用【杀】，', event.target2, '视为对', event.target1, '使用一张【杀】');
			event.target2.useCard({ name: 'sha', isCard: true }, event.target1, false);
		}
	},
	ai: {
		order: 8,
		result: {
			player: 1
		}
	}
},

"yxs_wangzuo": {
	audio: "ext:华夏风云/audio/peiyin:2",
	enable: "phaseUse",
	log: false,
	filter: function(event, player) {
		if (player.storage.yxs_wangzuo_recover && player.storage.yxs_wangzuo_lose) return false;
		if (!player.storage.yxs_wangzuo_recover && player.storage.yxs_wangzuo_lose) {
			return game.hasPlayer(function(current) {
				return current.isDamaged();
			});
		}
		return true;
	},
	ai: {
		order: 9,
		result: {
			player: function(player) {
				if (player.storage.yxs_wangzuo_recover && player.storage.yxs_wangzuo_lose) return 0;
				if (!player.storage.yxs_wangzuo_recover && player.storage.yxs_wangzuo_lose && !game.hasPlayer(function(c) { return c.isDamaged(); })) return 0;
				return 1;
			}
		}
	},
	content: function() {
		'step 0'
		var choices = [];
		var hasDamaged = game.hasPlayer(function(current) {
			return current.isDamaged();
		});
		
		if (!player.storage.yxs_wangzuo_recover && hasDamaged) {
			choices.push("回复1点体力并弃置2张牌");
		}
		if (!player.storage.yxs_wangzuo_lose) {
			choices.push("失去1点体力并摸2张牌");
		}
		choices.push("cancel2");
		
		player.chooseControl(choices).set("prompt", "王佐：请选择一项发动（各限1次）").set("ai", function() {
			if (choices.includes("失去1点体力并摸2张牌") && choices.includes("回复1点体力并弃置2张牌") && player.hp === player.maxHp) {
				return "失去1点体力并摸2张牌";
			}
			if (choices.includes("失去1点体力并摸2张牌")) return "失去1点体力并摸2张牌";
			return choices[0];
		});
		
		'step 1'
		if (result.control && result.control !== "cancel2") {
			event.choice = result.control;
			var is_recover = (event.choice === "回复1点体力并弃置2张牌");
			
			player.chooseTarget('王佐：选择一名角色执行【' + event.choice + '】', function(card, player, target) {
				if (is_recover) {
					return target.isDamaged();
				}
				return true;
			}).set('ai', function(target) {
				var att = get.attitude(player, target);
				if (is_recover) {
					if (att > 0) {
						var score = 3 + (target.maxHp - target.hp);
						if (target === player) score += 2;
						return score - target.countCards('he') * 0.3;
					}
					return 0;
				} else {
					if (att < 0) {
						if (target.hp === 1) return 12;
						return 4;
					}
					if (att > 0 && target.hp > 1) {
						if (target.hasSkillTag('maixie')) return 5;
						if (target === player) return 4.5;
						if (target.hp >= 3) return 3;
					}
					return 0;
				}
			});
		} else {
			event.finish();
		}
		
		'step 2'
		if (result.bool && result.targets && result.targets.length) {
			var target = result.targets[0];
			player.logSkill('yxs_wangzuo', target);
			if (event.choice === "回复1点体力并弃置2张牌") {
				player.storage.yxs_wangzuo_recover = true;
				target.recover();
				target.chooseToDiscard(2, true, 'he');
				game.log(player, '发动【王佐】，令', target, '回复了1点体力并弃置了2张牌');
			} else {
				player.storage.yxs_wangzuo_lose = true;
				target.loseHp();
				target.draw(2);
				game.log(player, '发动【王佐】，令', target, '失去了1点体力并摸了2张牌');
			}
		}
	},
	group: ["yxs_wangzuo_die", "yxs_wangzuo_clear"]
},

