             //黄忠
             
            yxs_liegong: {
	audio: "ext:华夏风云/audio/peiyin:2",
	// 规则修改：你的攻击范围至少为 X (X 为你本轮使用牌的数量)
	mod: {
		attackRange: function(player, num) {
			var x = player.getRoundHistory('useCard').length;
			return Math.max(num, x);
		}
	},
	// 修正：将增伤检测角色设为 source，确保作为伤害来源时精准触发
	trigger: {
		player: "useCardToBefore",
		source: "damageBegin1"
	},
	forced: true, // 锁定技自动触发
	popup: false,
	// 为技能增加可视化标记
	mark: true,
	marktext: "弓",
	intro: {
		content: function(storage, player) {
			return "你的当前攻击范围为：" + player.getAttackRange();
		},
		// 动态显示：在技能标记上实时渲染出您当前的攻击距离数字
		markcount: function(storage, player) {
			return player.getAttackRange();
		}
	},
	filter: function(event, player, name) {
		// 判定卡牌必须为【杀】
		if (!event.card || event.card.name !== 'sha') return false;
		
		// 锁定事件的目标（useCardToBefore 时为 event.target，damageBegin1 时为 event.player）
		var target = (name === "useCardToBefore") ? event.target : event.player;
		if (!target || target === player) return false;
		
		// 时机一：在指定目标前，如果攻击范围 <= 目标手牌数，触发“不可闪避”
		if (name === "useCardToBefore") {
			return player.getAttackRange() <= target.countCards('h');
		}
		
		// 时机二：在伤害结算前，如果攻击范围 >= 目标手牌数，触发“伤害翻倍”
		if (name === "damageBegin1") {
			return player.getAttackRange() >= target.countCards('h');
		}
		return false;
	},
	content: function() {
		if (event.triggername === "useCardToBefore") {
			trigger.directHit = true; // 设为必中
			game.log(player, '触发【烈弓】：当前攻击范围（' + player.getAttackRange() + '）小于等于目标手牌数，此【杀】不可闪避');
		} else if (event.triggername === "damageBegin1") {
			trigger.num *= 2; // 伤害点数翻倍
			game.log(player, '触发【烈弓】：当前攻击范围（' + player.getAttackRange() + '）大于等于目标手牌数，伤害翻倍');
		}
	}
},

    "yxs_fuli": {
	audio: "ext:华夏风云/audio/peiyin:2",
	trigger: {
		player: "phaseEnd" // 回合结束时
	},
	forced: true, // 锁定技自动触发
	filter: function(event, player) {
		// 判定1：本回合必须至少主动使用过 1 张【杀】
		var used_sha = player.getHistory('useCard', function(evt) {
			return evt.card && evt.card.name === 'sha';
		}).length > 0;
		if (!used_sha) return false;
		
		// 判定2：获取本回合由你的【杀】造成的所有伤害历史事件
		var history = player.getHistory('sourceDamage', function(evt) {
			return evt.card && evt.card.name === 'sha';
		});
		
		// 累加这些【杀】造成的总伤害
		var total_damage = 0;
		for (var i = 0; i < history.length; i++) {
			total_damage += history[i].num;
		}
		
		// 如果本回合造成的总伤害不为 1，则触发
		return total_damage !== 1;
	},
	content: function() {
		// 优先从摸牌堆或弃牌堆中锁定并获得 1 张【杀】
		var card = get.cardPile("sha") || get.discardPile(function(c) {
			return c.name === 'sha';
		});
		
		// 防干涸：如果所有牌堆都找不到任何【杀】，则直接从游戏外创建 1 张
		if (!card) {
			card = game.createCard("sha");
		}
		
		player.gain(card, "gain2");
		game.log(player, '触发【伏枥】，获得了一张【杀】');
	}
},

