			"GXS_jqzlweiwo": {
	audio: "ext:华夏风云/audio/peiyin:2",
	trigger: {
		global: ["chooseToRespondBegin", "chooseToUseBegin"]
	},
	frequent: true,
	popup: false,
	filter: function(event, player) {
		if (event.responded) return false;
		if (event.GXS_jqzlweiwo_prompt) return false;
		if (_status.currentPhase === player) return false;
		const target = event.player;
		if (target === player) return false;
		if (target.countCards('h') >= player.countCards('h')) return false;
		if (player.countCards('h') === 0) return false;
		if (!event.filterCard || !event.filterCard({ name: "shan" }, target, event)) return false;
		return true;
	},
	check: function(event, player) {
		return get.attitude(player, event.player) > 0;
	},
	logTarget: "player",
	init: function(player) {
		game.addGlobalSkill('GXS_jqzlweiwo_global');
	},
	onremove: function(player) {
		game.removeGlobalSkill('GXS_jqzlweiwo_global');
	},
	async content(event, trigger, player) {
		trigger.GXS_jqzlweiwo_prompt = true;
		const result = await player.chooseToDiscard('h', true, "帷幄：是否弃置一张手牌，视为 " + get.translation(trigger.player) + " 打出了一张【闪】？").forResult();
		if (result.bool) {
			trigger.untrigger();
			trigger.set("responded", true);
			trigger.result = { bool: true, card: { name: "shan", isCard: true } };
			game.log(player, '触发【帷幄】', trigger.player, '使用/打出了一张【闪】');
		}
	},
	subSkill: {
		"global": {
			charlotte: true,
			hiddenCard: function(player, name) {
				const owner = game.findPlayer(function(current) {
					return current.hasSkill('GXS_jqzlweiwo', null, null, false);
				});
				if (owner && owner !== player && owner.countCards('h') > 0 && name === 'shan') {
					return true;
				}
			},
			ai: {
				respondShan: true,
				freeShan: true,
				skillTagFilter(player, tag, arg) {
					if (tag !== "respondShan" && tag !== "freeShan") return;
					const owner = game.findPlayer(function(current) {
						return current.hasSkill('GXS_jqzlweiwo', null, null, false);
					});
					return owner && owner.countCards('h') > 0;
				}
			}
		}
	}
},

