          "yhuasheng": {
	enable: "phaseUse",
	filter: function(event, player) {
		if (!player.countCards("hes")) return false;
		for (var name of lib.inpile) {
			if (get.type(name) === "trick" && get.subtype(name) !== "delay" && name !== "wuxie") {
				if (player.hasStorage("yhuasheng_used", name)) continue;
				if (event.filterCard(get.autoViewAs({ name: name }, "unsure"), player, event)) return true;
			}
		}
		return false;
	},
	chooseButton: {
		dialog: function(event, player) {
			var list = [];
			for (var name of lib.inpile) {
				if (get.type(name) === "trick" && get.subtype(name) !== "delay" && name !== "wuxie") {
					if (player.hasStorage("yhuasheng_used", name)) continue;
					if (event.filterCard(get.autoViewAs({ name: name }, "unsure"), player, event)) {
						list.push(["锦囊", "", name]);
					}
				}
			}
			return ui.create.dialog("画圣", [list, "vcard"]);
		},
		check: function(button) {
			var player = _status.event.player;
			if (player.hasStorage("yhuasheng_used", button.link[2])) return 0;
			return player.getUseValue({ name: button.link[2] });
		},
		backup: function(links, player) {
			var name = links[0][2];
			return {
				filterCard: function(card, player) {
					if (card.name === 'sha') return true;
					var hasWusheng = player.hasSkill('wusheng') || player.hasSkill('new_rewusheng');
					if (hasWusheng && get.color(card) === 'red') return true;
					return false;
				},
				selectCard: 1,
				position: "hes",
				popname: true,
				viewAs: { name: name, isCard: true },
				async precontent(event, trigger, player) {
					player.logSkill("yhuasheng");
					game.log(player, "将", event.cards, "当作", get.translation(name), "使用");
					if (!player.storage.yhuasheng_used) {
						player.when({ global: "phaseAfter" }).step(async () => {
							delete player.storage.yhuasheng_used;
						});
					}
					player.markAuto("yhuasheng_used", name);
				}
			};
		},
		prompt: function(links, player) {
			return "将一张【杀】（拥有武圣或界武圣时可为红色牌）当作【" + get.translation(links[0][2]) + "】使用（每回合每种牌名限一次）";
		}
	},
	hiddenCard: function(player, name) {
		if (!lib.inpile.includes(name)) return false;
		if (name === 'wuxie') return false;
		if (player.hasStorage("yhuasheng_used", name)) return false;
		return get.type(name) === "trick" && get.subtype(name) !== "delay";
	},
	ai: {
		order: 1,
		result: {
			player: 1,
		}
	}
},  
		
