     yxs_zaokong: {
    audio: "ext:华夏风云/audio/peiyin:2",
    trigger: {
        player: "useCard",
        target: "useCardToTargeted"
    },
    filter: function (event, player) {
        if (!get.tag(event.card, 'damage')) return false;
        var key = event.card.name;
        var used = player.getStorage('yxs_zaokong_used') || [];
        if (used.includes(key)) return false;
        if (event.name == 'useCardToTargeted') {
            var parent = event.getParent();
            if (parent._yxs_zaokong_triggered) return false;
            parent._yxs_zaokong_triggered = true;
        }
        return true;
    },
    // ====== AI 是否发动 ======
    check: function (event, player) {
        var sourceEvent = (event.name == 'useCardToTargeted') ? event.getParent() : event;
        var targets = sourceEvent.targets;
        if (!targets || targets.length === 0) return false;

        if (event.name == 'useCardToTargeted') {
            // 自己成为目标
            var source = sourceEvent.source;
            var att = source ? get.attitude(player, source) : 0;
            if (att > 0) return false; // 友方使用的牌不规避

            // 遍历所有可选目标，看最优收益是否 > 0
            var bestScore = -Infinity;
            var cardDamage = get.tag(sourceEvent.card, 'damage') || 1;
            for (var i = 0; i < targets.length; i++) {
                var t = targets[i];
                var tAtt = get.attitude(player, t);
                var dist = Math.max(get.distance(player, t), 1);
                var score = 0;
                score += tAtt * cardDamage * 2;  // 保护友方为正，保护敌方为负
                score += dist * 0.8;             // 自己摸牌收益
                score -= (tAtt > 0 ? 0.5 : 1);  // 目标多摸1张的代价
                if (score > bestScore) bestScore = score;
            }
            return bestScore > 0;
        } else {
            // 自己使用的伤害牌
            var cardDamage = get.tag(event.card, 'damage') || 1;
            var bestScore = -Infinity;
            for (var i = 0; i < targets.length; i++) {
                var t = targets[i];
                var tAtt = get.attitude(player, t);
                var dist = Math.max(get.distance(player, t), 1);
                var score;
                if (tAtt > 0) {
                    // 移除友方：避免误伤 + 摸牌 > 友方多摸1张
                    score = cardDamage * 2 + dist * 0.8 - 1;
                } else {
                    // 移除敌方：自己摸牌 vs 敌方免伤+多摸
                    score = dist * 0.8 - cardDamage * 2 - 1.5;
                }
                if (score > bestScore) bestScore = score;
            }
            return bestScore > 0;
        }
    },
    content: function () {
        "step 0"
        var sourceEvent = (trigger.name == 'useCardToTargeted') ? trigger.getParent() : trigger;
        event._zaokong_source = sourceEvent;
        var allTargets = sourceEvent.targets.slice();
        if (allTargets.length === 0) {
            event.finish();
            return;
        }
        player.chooseTarget("请选择一名目标使其失效（该目标摸一张牌，你摸距离张牌）", function (card, player, target) {
            return allTargets.includes(target);
        }).set('ai', function (target) {
            var att = get.attitude(player, target);
            var dist = Math.max(get.distance(player, target), 1);
            var cardDamage = get.tag(trigger.card, 'damage') || 1;
            var remaining = event._zaokong_source.targets.length;
            var score = 0;

            // ---- 关键判断：移除后是否取消整张牌 ----
            if (remaining <= 1) {
                if (trigger.name == 'useCardToTargeted') {
                    // 取消敌人的牌，巨大收益
                    return 200 + dist;
                }
                // 取消自己用的牌，巨大损失
                return -200;
            }

            if (att > 0) {
                // ====== 移除友方目标 ======
                // 核心：保护友方免伤 + 自己摸距离张牌
                score = 20;                         // 基础保护意愿
                score += cardDamage * 3;            // 伤害越高越值得保护
                score += Math.max(0, 4 - target.hp) * 3; // 友方血量越低越优先
                score += Math.min(dist, 6) * 0.8;   // 距离远摸牌多，额外收益
                score -= 0.5;                        // 友方多摸1张的微小代价
            } else {
                // ====== 移除敌方目标 ======
                // 让敌人免伤（负面）+ 敌人多摸1张（负面）+ 自己摸dist张（正面）
                var damageCost = cardDamage * 3;        // 敌方免伤的代价权重
                var enemyDrawCost = 2;                   // 敌方多摸1张的代价权重
                var selfDrawGain = Math.min(dist, 6) * 1.5; // 自己摸牌收益权重

                score = selfDrawGain - damageCost - enemyDrawCost;
                // 收益不够时加大惩罚，避免无意义移除
                if (score < 0) score -= 10;
            }

            return score;
        });
        "step 1"
        if (result.bool && result.targets && result.targets[0]) {
            var chosen = result.targets[0];
            var key = trigger.card.name;
            var used = player.getStorage('yxs_zaokong_used') || [];
            used.push(key);
            player.setStorage('yxs_zaokong_used', used);
            var targets = event._zaokong_source.targets;
            targets.remove(chosen);
            if (targets.length === 0) {
                trigger.cancel();
            }
            chosen.draw(1);
            var dist = get.distance(player, chosen);
            player.draw(dist);
            game.log(player, '发动了凿空，令', chosen, '摸1牌，自己摸', dist, '牌');
        }
    },
    subSkill: {
        clear: {
            trigger: { player: "phaseEnd" },
            forced: true,
            popup: false,
            content: function () {
                player.removeStorage('yxs_zaokong_used');
            },
            sub: true,
        }
    },
    group: ["yxs_zaokong_clear"],
    ai: {
        threaten: 1.2
    }
},
            
