			GXS_wugu: {
    audio: 1,
    trigger: {
        global: "judgeBegin",
    },
    direct: true,
    async content(event, trigger, player) {
        const judgePlayer = trigger.player;

        const useResult = await player.chooseBool(
            get.prompt("GXS_wugu", judgePlayer),
            "是否发动【巫蛊】？摸一张牌，然后将任意张手牌置于牌堆顶"
        )
            .set("ai", () => {
                const player = get.player();
                const judgePlayer = _status.event.judgePlayer;
                if (!judgePlayer) return true;

                const att = get.attitude(player, judgePlayer);

                // 对友方：有低价值牌可以放牌堆顶时才发动
                if (att > 0) {
                    const lowCards = player.countCards("h", card => {
                        return get.value(card, player) <= 3;
                    });
                    return lowCards >= 1;
                }

                // 对敌方：有牌能操控判定结果时发动
                if (att < 0) {
                    return player.countCards("h") > 0;
                }

                return false;
            })
            .set("judgePlayer", judgePlayer)
            .forResult();

        if (!useResult.bool) return;

        player.logSkill("GXS_wugu", judgePlayer);

        // 摸一张牌
        await player.draw();

        if (!player.countCards("h")) return;

        // 选择任意张手牌
        const result = await player.chooseCard(
            [1, 10],
            "h",
            "巫蛊：请选择任意张手牌置于牌堆顶"
        )
            .set("ai", card => {
                const player = get.player();
                const judgePlayer = _status.event.judgePlayer;
                const att = get.attitude(player, judgePlayer);

                // 对友方：优先放低价值牌
                if (att > 0) {
                    return -get.value(card, player);
                }

                // 对敌方：优先放对判定有利的牌
                const name = get.name(card);
                if (name == "shan") return 12;
                if (name == "tao") return 11;
                if (name == "jiu") return 10;
                if (name == "sha") return 9;

                return -get.value(card, player);
            })
            .set("judgePlayer", judgePlayer)
            .forResult();

        if (!result.bool || !result.cards?.length) return;

        const chosenCards = result.cards.slice();

        // 失去这些牌
        await player.lose(chosenCards, ui.cardPile);

        // 选择放置顺序
        const orderResult = await player.chooseButton(
            chosenCards.length,
            true,
            ["巫蛊：按顺序将卡牌置于牌堆顶（先选择的在上）", chosenCards]
        )
            .set("ai", function (button) {
                const player = get.player();
                const judgePlayer = _status.event.judgePlayer;
                const att = get.attitude(player, judgePlayer);

                // 对友方：把最不需要的放最上面
                if (att > 0) {
                    return get.value(button.link, player);
                }

                // 对敌方：把判定最有利的放最上面
                const name = get.name(button.link);
                if (name == "shan") return 15;
                if (name == "tao") return 14;
                if (name == "jiu") return 13;
                if (name == "sha") return 12;

                return -get.value(button.link, player);
            })
            .set("judgePlayer", judgePlayer)
            .forResult();

        // 放置到牌堆顶
        if (orderResult.bool && orderResult.links?.length) {
            const cards = orderResult.links.slice();
            while (cards.length) {
                const card = cards.pop();
                card.fix();
                ui.cardPile.insertBefore(card, ui.cardPile.firstChild);
            }
        }
        else {
            for (let i = chosenCards.length - 1; i >= 0; i--) {
                chosenCards[i].fix();
                ui.cardPile.insertBefore(chosenCards[i], ui.cardPile.firstChild);
            }
        }

        game.updateRoundNumber();
    },
    ai: {
        expose: 0.1,
        rejudge: true,
        tag: {
            rejudge: 0.5,
        },
        result: {
            player(player, target) {
                const att = get.attitude(player, target);
                if (att > 0) {
                    const lowCards = player.countCards("h", card => get.value(card, player) <= 3);
                    return lowCards >= 1 ? 1 : 0;
                }
                if (att < 0) {
                    return player.countCards("h") > 0 ? 1 : 0;
                }
                return 0;
            },
        },
    },
},
			
