           "yqicuo": {
	audio: "ext:华夏风云/audio/peiyin:2",
	trigger: {
		global: ["loseAfter", "loseAsyncAfter"],
	},
	priority: 96,
	usable: 1,
	preHidden: true,
	filter: function (event, player) {
		var target = _status.currentPhase;
		if (!target || !target.isIn() || event.type != 'discard') return false;
		if (target != event.player) return false;
		var evt = event.getl(target);
		for (var i of evt.hs) {
			if (get.position(i, true) == 'd') return true;
		}
		return false;
	},
	content: function () {
		'step 0'
		event.target = _status.currentPhase;
		event.cards = trigger.getl(event.target).hs.filterInD('d');
		var str = '你可以发动【绮错】令' + get.translation(event.target) + '获得一张牌，或点击取消令其结束出牌阶段';
		var bool = !trigger.player.isPhaseUsing();
		player.chooseCardButton(str, event.cards, bool).set('ai', function (button) {
			var card = button.link;
			var source = trigger.player;
			if (get.attitude(player, source) > 0) {
				return Math.max(1, source.getUseValue(card, null, true));
			} else return false;
			var cards = _status.event.getParent().cards.slice(0);
			if (cards.length == 1) return -get.value(card);
			cards.remove(card);
			return (get.value(cards) - get.value(card) - 2);
		}).set('source', event.target).setHiddenSkill(event.name);
		'step 1'
		if (result.bool) {
			player.line(trigger.player);
			target.$gain2(result.links[0]);
			target.gain(result.links[0], 'log');
			game.log(player, '发动了', '#g' + '【绮错】', '令', trigger.player, '获得了一张弃牌');
		}
		else {
			var evt = _status.event.getParent('phaseUse');
			if (evt && evt.name == 'phaseUse') {
				evt.finish(); // 直接对其调用底层 evt.finish() 来结束出牌阶段
				player.line(trigger.player);
				game.log(player, '发动了', '#g' + '【绮错】', '令', trigger.player, '结束了出牌阶段');
				event.finish();
			}
		};
	},
},

