           "ztjx_benyue": {
	audio: "ext:华夏风云/audio/peiyin:2",
	enable: 'phaseUse', // 出牌阶段主动技，确保转化按钮在武将牌上完美高亮亮起！
	viewAs: {
		name: 'wuzhong' // 转化为【无中生有】
	},
	viewAsFilter(player) {
		// 采用您提供的 GXS_benyue 原生大写/对象过滤语法进行装备判定
		if (player.countCards('he', { type: 'equip' }) === 0) return false;
		
		var used = player.storage.ztjx_benyue_used || [];
		if (used.length >= 2) return false; // 如果红、黑两种颜色本回合均已用过，则按钮变暗
		
		// 只有拥有尚未被使用过颜色的装备牌时，按钮才高亮亮起
		var equips = player.getCards('he', { type: 'equip' });
		for (var i = 0; i < equips.length; i++) {
			var color = get.color(equips[i]);
			if (!used.includes(color)) return true;
		}
		return false;
	},
	filterCard: function(card, player) {
		// 判定选中的牌必须为装备牌
		if (get.type(card) !== 'equip') return false;
		
		// 过滤已被使用过的花色颜色（红 / 黑），确保点开按钮后只能选中合法的花色装备
		var color = get.color(card);
		var used = player.storage.ztjx_benyue_used || [];
		return !used.includes(color);
	},
	position: 'he', // 允许使用手牌或装备区里的装备牌进行转化
	
	// 关联：记录转化卡牌颜色、回合结束清理缓存 两个后台静默子技能
	group: ["ztjx_benyue_record", "ztjx_benyue_clear"],
	subSkill: {
		// 子技能一：专门负责在后台监听卡牌使用，记录颜色（隔离根过滤器冲突）
		"record": {
			charlotte: true,
			forced: true,
			popup: false,
			trigger: {
				player: "useCard1"
			},
			filter: function(event, player) {
				return event.skill === 'ztjx_benyue';
			},
			content: function() {
				var card = trigger.cards[0];
				var color = get.color(card);
				if (!player.storage.ztjx_benyue_used) {
					player.storage.ztjx_benyue_used = [];
				}
				player.storage.ztjx_benyue_used.add(color);
				game.log(player, '通过【奔月】转化了', get.translation(color) + '色', '的装备牌', card);
			}
		},
		// 子技能二：回合结束自动清除本回合的使用颜色标记（完全静默，不弹气泡）
		"clear": {
			charlotte: true,
			forced: true,
			popup: false,
			trigger: {
				player: "phaseAfter"
			},
			content: function() {
				delete player.storage.ztjx_benyue_used;
			}
		}
	},
	check: function(card) {
		// AI 策略（参考您的源码）：优先用手牌中价值较低的装备转化
		return 8 - get.value(card);
	}
},

