             "ztjx_pudu": {
	audio: "ext:华夏风云/audio/peiyin:2",
	enable: 'phaseUse',
	usable: 1, // 出牌阶段限 1 次
	filter: function(event, player) {
		// 装备区必须有至少 1 张牌才可以发动本技能
		return player.countCards('e') > 0;
	},
	content: function() {
		'step 0'
		// 1. 安全确认：询问玩家是否确认发动，防止误触导致装备区瞬间被清空
		player.chooseBool('是否弃置你装备区里的所有牌，发动【普渡】？').set('ai', function() {
			return true; // AI 默认选择确认发动
		});
		
		'step 1'
		if (result.bool) {
			// 2. 扣减装备区所有卡牌，并记录数量 X
			var equips = player.getCards('e');
			event.num = equips.length;
			if (event.num > 0) {
				player.discard(equips);
				game.log(player, '发动了【普渡】，弃置了装备区里的', event.num, '张牌');
			} else {
				// 安全降级：若因突发状况没有装备可弃置，终止结算
				event.finish();
				return;
			}
		} else {
			// 3. 玩家如果点击取消，则无损退回本阶段的发动次数限制，允许重新点开
			var stat = player.getStat('skill') || player.getStat().skill;
			if (stat && stat.ztjx_pudu) {
				stat.ztjx_pudu--;
			}
			event.finish();
			return;
		}
		
		'step 2'
		// 4. 选择“先选者”（AI 会百分之百聪明地选择友方进行大额摸牌）
		player.chooseTarget('普渡：请选择先选者，令其摸 ' + event.num + ' 张牌').set('ai', function(target) {
			return get.attitude(player, target);
		});
		
		'step 3'
		if (result.bool) {
			event.first_target = result.targets[0];
		} else {
			// 防卡死：如果未选目标退出，直接终止
			event.finish();
			return;
		}
		
		// 5. 选择“后选者”（必须是非先选者的其他角色，AI 会百分之百聪明地锁定敌人进行弃手牌打击）
		player.chooseTarget('普渡：请选择后选者，令其弃置 ' + event.num + ' 张手牌')
			.set('filterTarget', function(card, player, target) {
				return target !== event.first_target; // 强行排除掉先选者
			})
			.set('ai', function(target) {
				return -get.attitude(player, target);
			});
			
		'step 4'
		if (result.bool) {
			event.second_target = result.targets[0];
			
			// 6. 执行结算：先选者摸牌，后选者弃手牌
			event.first_target.draw(event.num);
			event.second_target.chooseToDiscard(event.num, true, 'h'); // 'h' 严格限制为弃置手牌（符合“弃x张手牌”描述）
		}
	},
	ai: {
		order: 8, // 高优先级
		result: {
			player: function(player) {
				return 1;
			}
		}
	}
},

