"yxs_zhuangbian": {
	audio: "ext:华夏风云/audio/peiyin:2",
	direct: true,
	trigger: {
		global: ["gainAfter", "loseAsyncAfter"]
	},
	filter: function(event, player) {
		if (player.hasHistory('useSkill', function(evt) {
			return evt.skill === 'yxs_zhuangbian';
		})) return false;
		
		var target = event.player;
		if (!target || !target.isIn()) return false;
		
		var evt = event.getParent('phaseDraw');
		if (evt && evt.name === 'phaseDraw') return false;
		
		if (target.storage.yxs_zhuangbian_gained) return false;
		
		return target.countCards('he') > 0;
	},
	content: function() {
		'step 0'
		event.target = trigger.player;
		player.chooseBool('妆变：是否获得 ' + get.translation(event.target) + ' 的一张牌并改变其性别直至其受到2次伤害？').set('ai', function() {
			return get.attitude(player, event.target) < 0;
		});
		'step 1'
		target.storage.yxs_zhuangbian_gained = true;
		
		if (result.bool) {
			player.logSkill('yxs_zhuangbian', target);
			player.gainPlayerCard(target, 'he', true);
		} else {
			event.finish();
			return;
		}
		'step 2'
		var oldSex = target.sex;
		var newSex = (oldSex === 'male') ? 'female' : 'male';
		
		target.storage.yxs_zhuangbian_old_sex = oldSex;
		target.storage.yxs_zhuangbian_damage_count = 0;
		target.sex = newSex;
		
		target.addSkill('yxs_zhuangbian_gender');
		target.markSkill('yxs_zhuangbian_gender');
		game.log(player, '将', target, '的性别改变为了', get.translation(newSex));
	},
	group: ["yxs_zhuangbian_clear"],
	subSkill: {
		"clear": {
			charlotte: true,
			forced: true,
			popup: false,
			silent: true,
			trigger: {
				global: "phaseAfter"
			},
			content: function() {
				game.players.forEach(function(current) {
					delete current.storage.yxs_zhuangbian_gained;
				});
			}
		},
		"gender": {
			charlotte: true,
			onremove: function(player) {
				if (player && player.storage && player.storage.yxs_zhuangbian_old_sex) {
					player.sex = player.storage.yxs_zhuangbian_old_sex;
					player.unmarkSkill('yxs_zhuangbian_gender');
					delete player.storage.yxs_zhuangbian_old_sex;
					delete player.storage.yxs_zhuangbian_damage_count;
					game.log(player, '的【妆变】性别改变效果已恢复');
				}
			},
			mark: true,
			marktext: "变",
			intro: {
				content: function(storage, player) {
					return "性别已被改变为：" + get.translation(player.sex) + "，受到 " + (2 - (player.storage.yxs_zhuangbian_damage_count || 0)) + " 次伤害后恢复。";
				}
			},
			trigger: {
				player: "damageEnd"
			},
			forced: true,
			popup: false,
			content: function() {
				if (!player.storage.yxs_zhuangbian_damage_count) {
					player.storage.yxs_zhuangbian_damage_count = 0;
				}
				player.storage.yxs_zhuangbian_damage_count += trigger.num;
				if (player.storage.yxs_zhuangbian_damage_count >= 2) {
					player.removeSkill('yxs_zhuangbian_gender');
				} else {
					player.markSkill('yxs_zhuangbian_gender');
				}
			}
		}
	}
},


      //常惠

       yxs_hanwei: {
	audio: "ext:华夏风云/audio/peiyin:2",
	enable: "phaseUse",
	position: "he",
	discard: false,
	lose: false,
	filterCard: function(card, player) {
		if (get.type(card) !== 'equip') return false;
		const subtype = get.subtype(card);
		return game.hasPlayer(function(target) {
			return target !== player && target.hasEmptySlot(subtype);
		});
	},
	filterTarget: function(card, player, target) {
		if (!card) return false;
		return target !== player && target.hasEmptySlot(get.subtype(card));
	},
	selectCard: 1,
	selectTarget: 1,
	check: function(card) {
		var player = _status.currentPhase;
		if (player.countCards('he', { subtype: get.subtype(card) }) > 1) {
			return 11 - get.equipValue(card);
		}
		return 6 - get.value(card);
	},
	prepare: function(cards, player, targets) {
		player.$give(cards, targets[0], false);
	},
	content: function() {
		'step 0'
		const card = event.cards[0];
		const target = event.targets[0];
		event.equip_target = target;
		target.equip(card);
		game.log(player, '将', card, '置入了', target, '的装备区');
		
		player.chooseTarget('汉威：请选择一名角色，令 ' + get.translation(target) + ' 对其使用一张【杀】', function(card, player, current) {
			return current !== event.equip_target;
		}).set('ai', function(current) {
			var player = get.player();
			return -get.attitude(player, current);
		});
		
		'step 1'
		if (result.bool && result.targets && result.targets[0]) {
			const slashTarget = result.targets[0];
			player.line(slashTarget, 'red');
			const next = event.equip_target.chooseToUse({name: 'sha'}, slashTarget);
			next.set('openskilldialog', '汉威：你已被指定，可以对 ' + get.translation(slashTarget) + ' 使用一张【杀】（无距离与次数限制）');
			next.set('addCount', false);
			next.forResult();
		}
	},
	ai: {
		order: 7,
		result: {
			player: 1,
			target: function(player, target) {
				if (get.attitude(player, target) <= 0) return 0;
				
				const card = ui.selected.cards[0];
				if (card) {
					return get.equipValue(card, target);
				}
				return 1;
			}
		}
	}
},

       yxs_zhiyi: {
	audio: "ext:华夏风云/audio/peiyin:2",
	trigger: {
		global: "damageBegin1"
	},
	filter: function(event, player) {
		if (_status.currentPhase !== player) return false;
		const source = event.source;
		return source && source !== player && source.isAlive();
	},
	content: function() {
		'step 0'
		event.source = trigger.source;
		const choices = ["各摸一牌"];
		if (event.source.countCards('he') > 0) {
			choices.push("弃置其一牌");
		}
		choices.push("cancel2");
		
		player.chooseControl(choices)
			.set("prompt", "制夷：选择一项对 " + get.translation(event.source) + " 发动")
			.set("ai", function() {
				var player = get.player();
				var source = get.event().getParent().source;
				if (get.attitude(player, source) > 0) {
					return "各摸一牌";
				}
				if (choices.includes("弃置其一牌")) {
					return "弃置其一牌";
				}
				return "cancel2";
			});
		'step 1'
		const choice = result.control;
		if (choice === "各摸一牌") {
			player.logSkill('yxs_zhiyi', event.source);
			player.draw();
			event.source.draw();
		} else if (choice === "弃置其一牌") {
			player.logSkill('yxs_zhiyi', event.source);
			player.discardPlayerCard(event.source, 'he', true);
		}
	}
},

               
